const cargasPendientes = new Set();
function registrarCarga(tarea,campo) {
 const seleccion=campo?.files?.[0];
 const carga = tarea.catch(error => {
  if(campo&&(!campo.isConnected||campo.files?.[0]!==seleccion))return;
  if(campo)campo.value='';
  console.warn(error);
  alert('No se pudo cargar una de las imágenes. Revisar el archivo.');
 }).finally(() => cargasPendientes.delete(carga));
 cargasPendientes.add(carga);
}

