function dibujarTrazadoInstitucional(g, nombre, x, y, ancho) {
  g.save();
  g.translate(x, y);
  g.scale(ancho / 1000, ancho / 1000);
  g.fill(trazadosInstitucionales[nombre]);
  g.restore();
}

const tipografiaFirmaInstitucional = '"Bembo oficial"';
async function cargarTipografiaFirmaInstitucional() {
 const caras=await document.fonts.load('400 32px '+tipografiaFirmaInstitucional,'Relaciones Exteriores ÁÉÍÓÚÑÜ');
 if(!caras.some(c=>c.status==='loaded'))
  throw new Error('No se pudo cargar la tipografía institucional del logotipo.');
}

function dibujarLogoInstitucional(g, logo, x, y, ancho, alto, color = logo.color, representacion = []) {
  g.save();
  g.translate(x, y);
  g.scale(ancho / logo.w, alto / logo.h);
  g.fillStyle = color;
  dibujarTrazadoInstitucional(g, ...logo.marca);
  if (logo.separador) {
    g.fillRect(...logo.separador);
    if (representacion.length) {
      const [inicio, , anchoLeyenda] = logo.leyenda;
      const [ , top, , altoRegla] = logo.separador;
      const altoLeyenda = altoRegla * .84;
      let tamaño = altoRegla / 6;
      let lineas, paso;
      do {
        g.font = '400 ' + tamaño + 'px ' + tipografiaFirmaInstitucional;
        lineas = representacion.flatMap(texto => lineasEditorial(g,texto.toLocaleUpperCase('es'),anchoLeyenda));
        paso = tamaño * 1.15;
        if (lineas.length * paso <= altoLeyenda) break;
        tamaño *= .9;
      } while (true);
      g.textAlign = 'left';
      g.textBaseline = 'top';
      const yLeyenda = top + (altoRegla - lineas.length * paso) / 2;
      lineas.forEach((linea,i) => g.fillText(linea,inicio,yLeyenda+i*paso));
    } else dibujarTrazadoInstitucional(g, 'ministerio', ...logo.leyenda);
  }
  g.restore();
}

const segmentadorGrafemas=typeof Intl.Segmenter==='function'?new Intl.Segmenter('es',{granularity:'grapheme'}):null;
function partirPalabra(g,palabra,ancho){
 const caracteres=segmentadorGrafemas?Array.from(segmentadorGrafemas.segment(palabra),letra=>letra.segment):Array.from(palabra);
 const partes=[];
 let parte='';
 for(const letra of caracteres){
  if(parte&&g.measureText(parte+letra).width>ancho){partes.push(parte);parte='';}
  parte+=letra;
 }
 partes.push(parte);
 return partes;
}

function wrap(g,texto,ancho,anchoPrimera=ancho){
 const lineas=[];
 for(const parrafo of String(texto??'').split('\n')){
  let linea='';
  for(const palabra of parrafo.split(' ')){
   const limite=lineas.length?ancho:anchoPrimera;
   if(linea&&g.measureText(linea+' '+palabra).width<=limite){
    linea+=' '+palabra;
    continue;
   }
   if(linea){lineas.push(linea);linea='';}
   const medida=g.measureText(palabra).width;
   if(!lineas.length&&anchoPrimera<ancho&&medida>anchoPrimera)lineas.push('');
   if(medida>(lineas.length?ancho:anchoPrimera)){
    const partes=partirPalabra(g,palabra,ancho);
    linea=partes.pop();
    lineas.push(...partes);
   }else linea=palabra;
  }
  lineas.push(linea);
 }
 return lineas;
}
function form(){$('locs').innerHTML=S.map((l,i)=>`<div class="card"><b>Sede ${i+1}</b>${S.length>1?` <button class="g" data-sec-click="S.splice(${i},1);form();go()">Quitar</button>`:''}
<div class="row"><div><label for="dui_city_${i}">Ciudad</label><input id="dui_city_${i}" value="${esc(l.c)}" placeholder="Indicar la ciudad y, si aplica, el estado o la provincia." data-sec-input="S[${i}].c=this.value;go()"></div><div><label for="dui_date_${i}">Fecha de la sede</label><input id="dui_date_${i}" value="${esc(l.f)}" placeholder="Indicar la fecha completa." data-sec-input="S[${i}].f=this.value;go()"></div></div>
<label for="dui_time_${i}">Horario</label><input id="dui_time_${i}" value="${esc(l.h)}" placeholder="Indicar el horario de atención. Ej.: 9:00 a. m. a 1:00 p. m." data-sec-input="S[${i}].h=this.value;go()">
<label for="dui_address_${i}">Dirección</label><textarea id="dui_address_${i}" placeholder="Incluir calle, número y referencia de acceso, si aplica." data-sec-input="S[${i}].d=this.value;go()">${esc(l.d)}</textarea></div>`).join('')}
