function encabezadoDui(o,datos){
 const {encabezado:hd,pais,fechaComun}=datos;
 const sB=hd?R.sub.b-109+o/2:147+o/2, cB=sB+153, gB=pais?cB+49:cB;
 const ultimo=fechaComun?gB:pais?cB:sB;
 return {hd,cB,gB,top:(hd||pais||fechaComun)?ultimo+85:null};
}

const margenDui=64, espacioColumnasDui=74;
function planDuiCuadricula(g,H,sedes,datos,P,ancha=false){
 const o=H-1350;
 const m={sc:fit(900,F,'Oxnard, CA',122.3),sd:fit(W7,F,'14 de noviembre de 2026',238.6),sa:fit(300,L,'3301 W Gonzales RD, Oxnard,',262.1)};
 const anchoFicha=ancha?680:(1080-2*margenDui-espacioColumnasDui)/2;
 const pasoCiudad=31;
 const fichas=sedes.map(sede=>{
  g.font=`300 ${m.sa}px ${L}`;
  const ad=wrap(g,sede.d,ancha?anchoFicha:330), aw=Math.max(...ad.map(t=>g.measureText(t).width));
  g.font=`${W7} ${m.sd}px ${F}`;
  const tx=[sede.f,sede.h].filter(Boolean).flatMap(t=>wrap(g,t,anchoFicha-58));
  const rw=Math.max(0,...tx.map(t=>g.measureText(t).width))+58;
  g.font=`900 ${m.sc}px ${F}`;
  const ciudad=wrap(g,sede.c,anchoFicha-31.1);
  const cw=31.1+Math.max(...ciudad.map(t=>g.measureText(t).width));
  const extra=(ciudad.length-1)*pasoCiudad;
  const regla=54.5+25.4*Math.max(0,tx.length-1)+10.8+extra;
  return {ad,tx,ciudad,rw,regla,extra,w:Math.max(aw,cw,rw),h:regla+24.3+24.8*(ad.length-1)+4};
 });
 const filas=[];
 for(let i=0;i<fichas.length;i+=2)filas.push(fichas.slice(i,i+2));
 const izquierda=Math.max(0,...filas.filter(f=>f.length>1).map(f=>f[0].w));
 const derecha=Math.max(0,...filas.filter(f=>f.length>1).map(f=>f[1].w));
 const x=540-(izquierda+espacioColumnasDui+derecha)/2;
 const posiciones=[];
 let y=0;
 for(const fila of filas){
  posiciones.push({ficha:fila[0],x:fila.length>1?x:540-fila[0].w/2,y});
  if(fila.length>1)posiciones.push({ficha:fila[1],x:x+izquierda+espacioColumnasDui,y});
  y+=Math.max(...fila.map(f=>f.h))+50;
 }
 const alto=y-50, limite=(datos.logos?1074:1290)+o;
 const arriba=P.top??Math.max(80+o/2,Math.min(668+o/2-alto/2,limite-alto));
 const desborde=arriba+alto>limite+.5;
 if(desborde&&sedes.length===1&&!ancha)return planDuiCuadricula(g,H,sedes,datos,P,true);
 return {P,dy:o/2-109,desborde,pintar(g){
  for(const {ficha:b,x,y:inicio} of posiciones){
   const y=inicio+arriba;
   g.drawImage(I.pin,x,y,R.city.pw*.76,R.city.ph*.76);
   g.font=`900 ${m.sc}px ${F}`;g.fillStyle=BL;g.textAlign='left';
   b.ciudad.forEach((t,i)=>g.fillText(t,x+31.1,y+24.5+i*pasoCiudad));
   g.font=`${W7} ${m.sd}px ${F}`;g.fillStyle=DK;
   b.tx.forEach((t,i)=>g.fillText(t,x+1.8,y+54.5+b.extra+25.4*i));
   g.fillRect(x,y+b.regla,b.rw,.35);
   g.font=`300 ${m.sa}px ${L}`;
   b.ad.forEach((t,i)=>g.fillText(t,x-1.5,y+b.regla+24.3+24.8*i));
  }
 }};
}

function planDuiClasico(g,H,sedes,datos,P){
 const o=H-1350;
 const ciudad=`900 ${fit(900,F,'Hamilton',R.city.w)}px ${F}`;
 const fecha=`${W7} ${fit(W7,F,'15 de noviembre de 2026',R.date.w)}px ${F}`;
 const direccion=`300 ${fit(300,L,'St East, Suite 101, Hamilton ON, L8N 1E8',R.addr.w)}px ${L}`;
 const altoDireccion=n=>R.addr.b+R.addr.p*(n-1)+8-R.city.py;
 const paso=R.date.p;
 const fichas=sedes.map(sede=>{
  g.font=ciudad;
  const nombres=wrap(g,sede.c,1080-margenDui-R.city.tx);
  g.font=fecha;
  const fechas=[sede.f,sede.h].flatMap(t=>wrap(g,t,1080-margenDui-R.date.x));
  g.font=direccion;
  const direcciones=wrap(g,sede.d,R.addr.w+12);
  const extraCiudad=(nombres.length-1)*paso, extra=extraCiudad+(fechas.length-2)*paso;
  return {nombres,fechas,direcciones,extraCiudad,extra,alto:altoDireccion(direcciones.length)+extra};
 });
 const total=fichas.reduce((alto,f,i)=>alto+f.alto+(i?GAP:0),0);
 const fin=R.city.py+total-8;
 const limite=datos.logos?Math.min(R.emb.y,R.rn.y)+o-25:H-R.bl.h-14;
 const dy=Math.max(100+o/2-R.pill.y,Math.min(o/2-(total-altoDireccion(2))/2,limite-fin));
 return {P,dy,desborde:dy+fin>limite+.5,pintar(g){
  let y=dy;
  g.textAlign='left';
  for(const b of fichas){
   g.drawImage(I.pin,R.city.px,R.city.py+y,R.city.pw,R.city.ph);
   g.font=ciudad;g.fillStyle=BL;
   b.nombres.forEach((t,i)=>g.fillText(t,R.city.tx,R.city.b+y+paso*i));
   g.font=fecha;g.fillStyle=DK;
   b.fechas.forEach((t,i)=>g.fillText(t,R.date.x,R.date.b+y+b.extraCiudad+paso*i));
   g.fillRect(R.rule.x,R.rule.y+y+b.extra,R.rule.w,.35);
   g.font=direccion;
   b.direcciones.forEach((t,i)=>g.fillText(t,R.date.x,R.addr.b+y+b.extra+R.addr.p*i));
   y+=b.alto+GAP;
  }
 }};
}

function prepararArtesDui(){
 const H=1350, o=0;
 const datos={titulo:$('t').value,subtitulo:$('s').value,pais:$('p').value,fechaComun:$('gd').value,
  cuadricula:$('lay').value==='gr',encabezado:$('hd').checked,logos:$('lg').checked};
 const P=encabezadoDui(o,datos);
 const g=document.createElement('canvas').getContext('2d');
 if(datos.cuadricula&&(datos.pais||datos.fechaComun))g.textAlign='center';
 else if(!datos.cuadricula||P.hd)g.textAlign='left';
 const planificar=datos.cuadricula?planDuiCuadricula:planDuiClasico;
 const paginas=[];
 let sedes=[], previo;
 for(const sede of S){
  if(!datos.cuadricula&&sedes.length===2){paginas.push(previo);sedes=[];}
  let plan=planificar(g,H,[...sedes,sede],datos,P);
  if(sedes.length&&plan.desborde){
   paginas.push(previo);sedes=[];
   plan=planificar(g,H,[sede],datos,P);
  }
  sedes.push(sede);previo=plan;
 }
 if(sedes.length)paginas.push(previo);
 const nombrePais=normalizarBusqueda(datos.pais).replace(/ /g,'-');
 const pais=nombrePais?'-'+nombrePais:'';
 return paginas.map((plan,i)=>({
  nombre:'dui'+pais+(H===1350?'-post-':'-historia-')+(i+1)+'.png',
  ancho:1080,alto:H,desborde:plan.desborde,
  mensajeDesborde:plan.desborde?'Una sede supera el espacio disponible. Revisa su dirección, fecha u horario.':'',
  dibujar:(K,banda)=>dibujarDui(H,datos,plan,K,banda)
 }));
}
function lienzoArte(ancho, alto, escala, banda) {
 const w = Math.round(ancho * escala), h = Math.round(alto * escala);
 const c = document.createElement('canvas');
 c.width = w;
 c.height = banda ? banda.alto : h;
 const g = c.getContext('2d', banda ? {willReadFrequently: true} : undefined);
 g.setTransform(w / ancho, 0, 0, h / alto, 0, banda ? -banda.y : 0);
 g.imageSmoothingQuality = 'high';
 return {c, g};
}
function dibujarDui(H,datos,plan,K,banda){
 const {c,g}=lienzoArte(1080,H,K,banda), o=H-1350, {P,dy}=plan;
 const ancho=1080-2*margenDui;
 g.fillStyle='#fff';g.fillRect(0,0,1080,H);
 g.drawImage(I.tr,R.tr.x,0,R.tr.w,R.tr.h);
 g.drawImage(I.bl,0,H-R.bl.h,R.bl.w,R.bl.h);
 const ajustar=(t,peso,ref,calibracion,limite)=>{
  const tamaño=fit(peso,F,ref,calibracion);
  g.font=peso+' '+tamaño+'px '+F;
  const natural=g.measureText(t).width;
  if(natural<=limite)return natural;
  const factor=limite/natural;
  if(factor<.7)c.desbordeEditorial=true;
  g.font=peso+' '+(tamaño*Math.max(.7,factor))+'px '+F;
  return limite;
 };
 const escribir=(t,x,y,color,alineacion,limite)=>{
  g.fillStyle=color;g.textAlign=alineacion;
  if(g.measureText(t).width>limite+.1)g.fillText(t,x,y,limite);
  else g.fillText(t,x,y);
 };
 if(!datos.cuadricula||P.hd){
  const anchoTitular=ajustar(datos.titulo,900,'Jornada de identificación',R.title.w,ancho-54);
  const w=Math.max(R.pill.w,anchoTitular+54);
  g.fillStyle=BL;g.beginPath();
  g.roundRect(540-w/2,R.pill.y+dy,w,R.pill.h,R.pill.h/2);g.fill();
  escribir(datos.titulo,540,R.title.b+dy,'#fff','center',ancho-54);
  const gap=R.sub.tx-R.sub.ix-R.sub.iw, limite=ancho-R.sub.iw-gap;
  const sw=ajustar(datos.subtitulo,900,'Enrolamiento de DUI',R.sub.w,limite);
  const x=540-(R.sub.iw+gap+sw)/2;
  g.drawImage(I.chk,x,R.sub.iy+dy,R.sub.iw,R.sub.ih);
  escribir(datos.subtitulo,x+R.sub.iw+gap,R.sub.b+dy,BL,'left',limite);
 }
 const escribirPais=(texto,y)=>{
  ajustar(texto,W7,'Canadá',R.ctry.w,ancho);
  escribir(texto,540,y,DK,'center',ancho);
 };
 if(datos.cuadricula){
  if(datos.pais)escribirPais(datos.pais,P.cB);
  if(datos.fechaComun)escribirPais(datos.fechaComun,P.gB);
 }else escribirPais(datos.pais,R.ctry.b+dy);

 plan.pintar(g);
 if(datos.logos){
  const {x,y,w,h}=R.emb;
  dibujarLogoInstitucional(g,logosInstitucionales.dui,x,y+o,w,h);
  g.drawImage(I.rn,R.rn.x,R.rn.y+o,R.rn.w,R.rn.h);
 }
 return c;
}
