function MVDesign(v){
 const [h,m]=String(v).split('|');
 if(!['left|photo','center|photo'].includes(String(v)))return;
 const p=MP();p.header=h;p.heroMode=(h==='banner'||h==='profile')?'off':(['photo','text','off'].includes(m)?m:'off');
 if(p.heroMode!=='photo')cargaFotoMov++;
 MVRefrescar('mvDiseno');
}
function MVDesignValue(p){return p.header+'|'+((p.header==='banner'||p.header==='profile')?'off':p.heroMode);}

const MV_MARCADOR=/^(?:[•●◦▪‣✓✔☑]\s*|(?:[–—*+-]|\d{1,3}[.)])\s+)/u;
const MV_DATO=/^(?:fecha(?: de (?:entrevista|aplicaci[oó]n|postulaci[oó]n|cierre)| l[ií]mite)?|hora(?:rio)?|lugar|ubicaci[oó]n|direcci[oó]n|modalidad(?: de [^:]{1,28})?|enlace|date|interview date|time|schedule|location|address|deadline|application (?:method|deadline)|link)\s*:/iu;
const MV_FECHA=/^(?:(?:lunes|martes|mi[eé]rcoles|jueves|viernes|s[aá]bado|domingo),? +)?\d{1,2} de [\p{L}]+ de \d{4}\.?$|^(?:(?:Monday|Tuesday|Wednesday|Thursday|Friday|Saturday|Sunday),? +)?(?:January|February|March|April|May|June|July|August|September|October|November|December) +\d{1,2},? +\d{4}\.?$/iu;
const MV_TITULO=/^(?:t[ií]tulo(?: del puesto)?|nombre del puesto|puesto|ocupaci[oó]n|vacante|job title|position(?: title)?|vacancy|role)$/iu;

function MVLeerEtiqueta(linea){
 const marcada=/^#{1,6}\s+/.test(linea);
 const limpia=linea.replace(/^#{1,6}\s+/,'').replace(/^\*\*([^*]+)\*\*/u,'$1').trim();
 const [nombre,texto='']=limpia.split(/[:：](.*)/su);
 const id=MV_ETIQUETAS_PEGADO.get(normalizarBusqueda(nombre));
 if(id)return {id,titulo:limpia.slice(0,limpia.length-texto.length).trimEnd(),texto:texto.trim()};
 if(MV_TITULO.test(nombre.trim())&&texto.trim())return {id:'titulo',titulo:texto.trim(),texto:''};
 if(marcada)return {id:'libre',titulo:limpia,texto:''};
 if(/^\*\*[^*]+[:：]\*\*/u.test(linea)&&texto.trim()&&!MV_DATO.test(limpia))
  return {id:'libre',titulo:limpia.slice(0,limpia.length-texto.length).trimEnd(),texto:texto.trim()};
 return null;
}

function MVEsEncabezadoLibre(linea,anterior,siguiente,actual,marcada){
 if(MV_MARCADOR.test(linea)||MV_DATO.test(linea)||!siguiente)return false;
 const palabras=linea.trim().split(/\s+/);
 const formato=/^\*\*[^*]+\*\*:?$/u.test(linea);
 const corta=palabras.length<=10&&linea.length<=90&&/^\p{L}/u.test(linea)&&!/[.;!?]$/u.test(linea);
 if((formato||/[:：]$/u.test(linea))&&corta)return true;
 // For unmarked text use paragraph boundaries and a plausible heading, preserving ambiguity as text.
 return !marcada&&!anterior&&corta&&actual?.hint!=='applicationFacts'&&
  !/[,;:]|\d|^(?:si|if|por favor|please|para |to |the |el |la |los |las )/iu.test(linea)&&
  (MV_MARCADOR.test(siguiente)||siguiente.length>linea.length+15);
}

function MVLeerConvocatorias(pegado){
 const lineas=pegado.replace(/^\uFEFF/u,'').replace(/\r\n?/g,'\n').split('\n');
 while(lineas.length&&!lineas.at(-1).trim())lineas.pop();
 if(!lineas.some(linea=>linea.trim()))return [];
 const noVacias=lineas.map((linea,i)=>({linea:linea.trim(),i})).filter(l=>l.linea);
 const inicios=[noVacias[0].i];
 let apartados=0, huboCierre=false;
 for(const [n,{linea,i}] of noVacias.entries()){
  const seccion=MVLeerEtiqueta(linea)?.id;
  const letras=linea.match(/\p{L}/gu)||[];
  const mayusculas=letras.length>=3&&linea.toLocaleUpperCase('es')===linea&&!/[:：.!?]$/u.test(linea);
  const numerada=/^\d{1,2}[.)]\s+/.test(linea);
  const proximas=noVacias.slice(n+1,n+8);
  const presenta=proximas.slice(0,2).some(({linea})=>/^(?:invitamos|se invita|buscamos|we invite|we are (?:seeking|looking)|we welcome)\b/iu.test(linea));
  const conSeccion=proximas.some(({linea})=>MVLeerEtiqueta(linea)?.id||MV_DATO.test(linea)||MV_FECHA.test(linea));
  if(n&&apartados&&(seccion==='titulo'||(!seccion&&presenta&&conSeccion&&(numerada||mayusculas||huboCierre)&&
     (numerada||!MV_MARCADOR.test(linea))&&linea.length<=150))){
   inicios.push(i);apartados=0;huboCierre=false;
  }
  if(seccion&&seccion!=='titulo'||MV_DATO.test(linea)||MV_FECHA.test(linea))apartados++;
  if(seccion==='documents'||seccion==='note')huboCierre=true;
 }

 return inicios.map((desde,i)=>{
  const partes=lineas.slice(desde,inicios[i+1]), primero=partes[0].trim();
  const etiqueta=MVLeerEtiqueta(primero);
  const tituloProbable=!etiqueta&&!MV_MARCADOR.test(primero)&&!MV_DATO.test(primero)&&
   !MV_FECHA.test(primero)&&!/[.!?;:]$/u.test(primero)&&primero.length<=160;
  const titulo=etiqueta?.id==='titulo'?etiqueta.titulo:tituloProbable?primero:etiqueta?.id==='libre'?etiqueta.titulo:'';
  if(titulo)partes.shift();
  const intro=[],blocks=[];
  const siguientes=Array(partes.length);
  let cercana='';
  for(let j=partes.length-1;j>=0;j--){
   siguientes[j]=cercana;
   cercana=partes[j].trim()||cercana;
  }
  let actual=null,marcadores=false;
  const abrir=(bloque)=>{
   actual=bloque;blocks.push(actual);marcadores=false;
  };
  for(let j=0;j<partes.length;j++){
   const cruda=partes[j],linea=cruda.trim();
   const siguiente=siguientes[j];
   const encabezado=MVLeerEtiqueta(linea);
   if(encabezado?.id==='libre'||encabezado?.id==='titulo'){
    abrir({k:MV_MARCADOR.test(siguiente||'')?'list':'p',t:encabezado.titulo,x:encabezado.texto});
   }else if(encabezado){
    abrir(MVSeccion(encabezado.id,encabezado.titulo,encabezado.texto));
   }else if((MV_DATO.test(linea)||MV_FECHA.test(linea))&&(!actual||actual.k==='facts')){
    if(!actual)abrir(MVSeccion('applicationFacts',''));
    actual.x+=(actual.x?'\n':'')+linea;
   }else if(!partes[j-1]?.trim()&&/^(?:if you (?:are interested and )?meet the requirements|si (?:te interesa(?: y)? |est[aá]s interesado(?: y)? )?cumples (?:con )?los requisitos)\b/iu.test(linea)){
    abrir({k:'cta',t:'',x:linea});
   }else if(MV_MARCADOR.test(linea)&&(!actual||['p','cta'].includes(actual.k)&&!actual.t&&actual.x)){
    const documentos=actual?.x.match(/(?:documents (?:with you|to (?:bring|present|submit))|documentos (?:a presentar|que debes presentar))/iu);
    abrir(documentos?MVSeccion('documents',''):{k:'list',t:'',x:''});
    actual.x=linea.replace(MV_MARCADOR,'');marcadores=true;
   }else if(MVEsEncabezadoLibre(linea,partes[j-1]?.trim(),siguiente,actual,marcadores)&&
     (actual?.k!=='facts'||/^#{1,6}\s/.test(linea)||/[:：]$/u.test(linea)&&MV_MARCADOR.test(siguiente))){
    const t=linea.replace(/^\*\*([^*]+)\*\*/u,'$1');
    abrir({k:MV_MARCADOR.test(siguiente||'')?'list':'p',t,x:''});
   }else if(actual){
    if(!linea){
     if(!MVEsLista(actual)&&actual.x)actual.x+='\n';
     continue;
    }
    const elemento=MVEsLista(actual)&&MV_MARCADOR.test(linea);
    if(MVEsLista(actual)&&marcadores&&!elemento&&!partes[j-1]?.trim()&&!/^\s+/u.test(cruda)){
     abrir({k:'p',t:'',x:linea});
    }else if(MVEsLista(actual)&&marcadores&&!elemento){
     actual.x+=' '+linea;
    }else{
     actual.x+=(actual.x?'\n':'')+(elemento?linea.replace(MV_MARCADOR,''):linea);
     if(elemento)marcadores=true;
    }
   }else intro.push(linea);
  }
  for(const bloque of blocks)bloque.x=bloque.x.trim();
  return {titulo,intro:intro.join('\n').trim(),blocks};
 });
}

function MVMontarOpcionesPegado(){
 const opciones=mvEditor.opciones||[];
 const selector=$('mvVacantePegar'),rango=$('mvVacanteCampo');
 selector.replaceChildren(...opciones.map((a,i)=>new Option(a.titulo||'Convocatoria '+(i+1),String(i))));
 selector.value=String(mvEditor.seleccion);
 rango.hidden=opciones.length<2;
 $('mvAplicarPegado').disabled=!mvEditor.pegado.trim();
}

function MVActualizarPegado(v){
 mvEditor.pegado=v;mvEditor.seleccion=0;mvEditor.opciones=null;
 mvEditor.mensaje='';
 $('mvEstadoPegado').hidden=true;
 $('mvEstadoPegado').textContent='';
 MVMontarOpcionesPegado();
}

function MVAplicarPegado(){
 const primeraLectura=!mvEditor.opciones;
 mvEditor.opciones??=MVLeerConvocatorias(mvEditor.pegado);
 if(primeraLectura&&mvEditor.opciones.length>1){
  MVMontarOpcionesPegado();
  const estado=$('mvEstadoPegado');
  mvEditor.mensaje='Hay varias convocatorias. Seleccionar un puesto y pulsar «Pasar al formulario».';
  estado.textContent=mvEditor.mensaje;estado.hidden=false;
  $('mvVacantePegar').focus();
  return;
 }
 const oferta=mvEditor.opciones[mvEditor.seleccion];
 if(!oferta||MVHayEdicion()&&!confirm('¿Reemplazar el puesto, la introducción y los apartados ya editados? Se conservará la fotografía y el diseño.'))return;
 const p=MP();
 p.heroTitle=oferta.titulo;p.heroText=oferta.intro;p.blocks=oferta.blocks.map(b=>({...b}));
 mvEditor.textoEditado=true;
 mvEditor.importarAbierto=false;
 mvEditor.mensaje=oferta.titulo?'Texto incorporado al formulario. Cada apartado es editable.':
  'Texto incorporado al formulario. Revisar el nombre del puesto.';
 MVRefrescar('mvTitulo');
}

function movForm(){
 const p=MP(),titular=p.header==='banner'||p.header==='profile';
 const sel=(opciones,valor)=>opciones.map(([id,nombre])=>`<option value="${esc(String(id))}"${id===valor?' selected':''}>${esc(nombre)}</option>`).join('');
 const control=(id,rotulo,valor,fn,{filas=0,placeholder=''}={})=>`<label for="${id}">${rotulo}</label>${
  filas?`<textarea id="${id}" rows="${filas}" placeholder="${esc(placeholder)}" data-sec-input="${fn}">${esc(valor||'')}</textarea>`:
  `<input id="${id}" value="${esc(valor||'')}" placeholder="${esc(placeholder)}" data-sec-input="${fn}">`}`;
 const blocks=p.blocks.map((b,i)=>{
  const seccion=MV_SECCIONES[b.hint];
  const nombre=seccion?.[1]||MV_TIPOS[b.k];
  const ayuda=seccion?.[2]||(MVEsLista(b)?'Un elemento por línea.':b.k==='cards'?'Separar los recuadros con una línea en blanco.':'');
  const esTexto=['p','facts','cta','note'].includes(b.k);
  const contenido=b.k==='page'?'<small class="field-help">El siguiente apartado empieza en una página nueva.</small>':
   control('mvEncabezado-'+i,'Encabezado editable',b.t,`MVB(${i},'t',this.value)`)+
   control('mvTexto-'+i,b.k==='facts'?'Fecha, horario, lugar y modalidad':b.k==='note'?'Texto de la nota':MVEsLista(b)?'Elementos':'Texto',
    b.x,`MVB(${i},'x',this.value)`,{filas:b.k==='facts'?4:3,placeholder:ayuda})+
   (MVEsLista(b)?'<small class="field-help">Un elemento por línea. Para destacar texto, usar **negrita**.</small>':'');
  return `<section class="mv-block" aria-labelledby="mvBloque-${i}"><h4 id="mvBloque-${i}">${esc(!seccion&&b.t?b.t:nombre)}</h4>
   ${contenido}
   <details class="mv-block-options"><summary>Opciones del apartado</summary>
    <label for="mvTipo-${i}">Presentación</label><select id="mvTipo-${i}" data-sec-change="MVCambiarTipo(${i},this.value)">${sel(Object.entries(MV_TIPOS),b.k)}</select>
    ${esTexto?`<label for="mvAncho-${i}">Ancho del texto</label><select id="mvAncho-${i}" data-sec-change="MVB(${i},'width',this.value)">${sel([['full','Completo'],['medium','Medio'],['narrow','Estrecho']],b.width||'full')}</select>`:''}
    ${MVEsLista(b)?`<label for="mvIcono-${i}">Marcador</label><select id="mvIcono-${i}" data-sec-change="MVB(${i},'icon',this.value)">${sel([['check','Verificación verde'],['dot','Punto azul'],['none','Sin marcador']],b.icon||'check')}</select>`:''}
    <div class="mv-actions">
     <button type="button" class="g" data-sec-click="MVMove(${i},-1)" ${i===0?'disabled':''}>Subir</button>
     <button type="button" class="g" data-sec-click="MVMove(${i},1)" ${i===p.blocks.length-1?'disabled':''}>Bajar</button>
     <button type="button" class="g" data-sec-click="MVDup(${i})">Duplicar</button>
     <button type="button" class="g" data-sec-click="MVDelete(${i})">Quitar</button>
    </div>
   </details></section>`;
 }).join('');
 const disenos=Object.entries(catalogoPlantillas.mov[''].variantes).map(([id,[nombre]])=>[id,nombre]);
 $('movf').innerHTML=`<div class="card">
  <details class="mv-paste" ${mvEditor.importarAbierto?'open':''} data-sec-toggle="mvEditor.importarAbierto=this.open">
   <summary>Pegar desde un documento</summary>
   <label for="mvPegado">Texto de la convocatoria</label>
   <textarea id="mvPegado" rows="5" placeholder="Pegar el texto desde el título hasta la nota final." data-sec-input="MVActualizarPegado(this.value)">${esc(mvEditor.pegado)}</textarea>
   <div id="mvVacanteCampo" hidden><label for="mvVacantePegar">Puesto de la convocatoria</label>
    <select id="mvVacantePegar" data-sec-change="mvEditor.seleccion=Number(this.value)"></select></div>
   <button type="button" id="mvAplicarPegado" data-sec-click="MVAplicarPegado()">Pasar al formulario</button>
  </details>
  <p id="mvEstadoPegado" role="status" class="field-help" ${mvEditor.mensaje?'':'hidden'}>${esc(mvEditor.mensaje)}</p>
  ${control('mvTitulo',titular?'Titular':'Nombre del puesto',p.heroTitle,`MVS('heroTitle',this.value)`,{filas:2})+
   control('mvIntro',titular?'Subtítulo':'Introducción de la convocatoria',p.heroText,`MVS('heroText',this.value)`,{filas:3})}
  <details class="mv-design" ${mvEditor.disenoAbierto?'open':''} data-sec-toggle="mvEditor.disenoAbierto=this.open">
   <summary>Fotografía y portada</summary>
   <label for="mvDiseno">Variante de portada</label><select id="mvDiseno" data-sec-change="MVDesign(this.value)">${sel(disenos,MVDesignValue(p))}</select>
   ${!titular?control('mvPrograma','Texto de la franja azul',p.programTitle,`MVS('programTitle',this.value)`):''}
   ${!titular&&p.heroMode==='photo'?`<label for="mvFoto">Fotografía</label><input id="mvFoto" type="file" accept="image/png,image/jpeg,image/webp" data-sec-change="registrarCarga(MVPhoto(this),this)">
    ${p.photoName?`<small class="field-help">${esc(p.photoName)}</small><button type="button" class="g" data-sec-click="MVRemovePhoto()">Quitar foto</button>
    <label for="mvFotoY">Encuadre vertical</label><input id="mvFotoY" type="range" min="0" max="100" value="${p.photoY}" data-sec-input="MVS('photoY',+this.value)">`:''}`:''}
  </details>
 </div>
 <div class="card">
  <h3>Contenido de la convocatoria</h3>
  ${blocks||'<p class="mv-empty">Pegar una convocatoria o agregar un apartado para comenzar.</p>'}
  <div class="mv-add"><div><label for="mvNewType">Tipo de apartado</label>
   <select id="mvNewType">${sel(Object.entries(MV_TIPOS),'p')}</select></div>
   <button type="button" data-sec-click="MVAdd($('mvNewType').value)">Agregar apartado</button>
  </div>
 </div>`;
 MVMontarOpcionesPegado();
}

const MVG={x:146,w:1433,text:39,line:47,head:42,headLine:54,blue:'#073270',light:'#bfe7fb',green:'#84d46c',cyan:'#6bc4dc',red:'#f16a7a'};
const MVEspaciadoBase={entre:44,titulo:14,datos:11,elemento:13,recuadro:52,tarjetas:20,accion:59};
const MVEspaciadoSuave={...MVEspaciadoBase,entre:36};
const MVEspaciadoCompacto={entre:24,titulo:10,datos:8,elemento:8,recuadro:44,tarjetas:14,accion:55};

const mvFont=(bold=false,size=MVG.text)=>`${bold?700:400} ${size}px ${bold?PF:'"AD Montserrat",Montserrat,sans-serif'}`;
function MVLines(g,t,w,bold=false,size=MVG.text){g.font=mvFont(bold,size);return wrap(g,String(t||''),w).filter(s=>s.trim())}
function MVText(g,s,x,y,bold=false,size=MVG.text,color=MVG.blue,center=false){g.font=mvFont(bold,size);g.fillStyle=color;g.textAlign=center?'center':'left';g.fillText(s,x,y)}
function MVLine(g,texto,x,y,ancho,pintar,color=MVG.blue,encabezado=''){
 const pos=texto.indexOf(':');
 let etiqueta=encabezado||(pos>0&&pos<=57&&!(/\d:\d/.test(texto.slice(pos-1,pos+2)))&&texto[pos+1]!=='/'
  ?texto.slice(0,pos+1):'');
 const lineas=MVLines(g,texto,ancho);
 let filas=lineas;
 let sangria=0;
 if(etiqueta&&lineas[0]?.startsWith(etiqueta)){
  g.font=mvFont(true);
  sangria=g.measureText(etiqueta).width+6;
  g.font=mvFont();
  const primero=lineas[0].slice(etiqueta.length).trimStart();
  if(sangria>=ancho)etiqueta='';
  else if(sangria+g.measureText(primero).width>ancho){
   filas=wrap(g,texto.slice(etiqueta.length).trimStart(),ancho,ancho-sangria);
   filas[0]=etiqueta+' '+filas[0];
  }
 }else etiqueta='';
 filas.forEach((linea,i)=>{
  if(pintar){
   if(!i&&etiqueta){
    MVText(g,etiqueta,x,y,true,MVG.text,color);
    MVText(g,linea.slice(etiqueta.length).trimStart(),x+sangria,y,false,MVG.text,color);
   }else MVText(g,linea,x,y,false,MVG.text,color);
  }
  y+=MVG.line;
 });
 return y;
}
function MVCheck(g,x,y){if(!g)return;if(I?.mvcheck){g.drawImage(I.mvcheck,x-26,y-26,52,52);return}g.save();g.strokeStyle=MVG.green;g.lineWidth=4.5;g.lineCap='round';g.lineJoin='round';g.beginPath();g.arc(x,y,17.5,Math.PI*1.77,Math.PI*3.42,false);g.stroke();g.beginPath();g.moveTo(x-9,y);g.lineTo(x-1,y+8);g.lineTo(x+17,y-13);g.stroke();g.restore()}
function MVPointer(g,x,y){if(I?.mvpointer){g.drawImage(I.mvpointer,x-34,y-32,66,67);return}g.save();g.strokeStyle='#69c0d9';g.lineWidth=6;g.lineCap='round';g.beginPath();g.arc(x,y,18,0.45,Math.PI*1.88);g.stroke();g.strokeStyle='#9bd6e4';g.lineWidth=4;g.beginPath();g.arc(x,y,9,0.8,Math.PI*1.7);g.stroke();g.fillStyle='#5db6d0';g.strokeStyle='#fff';g.lineWidth=2.5;g.beginPath();g.moveTo(x+2,y-3);g.lineTo(x+29,y+12);g.lineTo(x+15,y+17);g.lineTo(x+20,y+32);g.lineTo(x+10,y+35);g.lineTo(x+4,y+18);g.lineTo(x-3,y+27);g.closePath();g.fill();g.stroke();g.restore()}
function MVAlert(g,x,y){if(I?.mvalert){g.drawImage(I.mvalert,x-32,y-32,64,65);return}g.save();g.fillStyle=MVG.red;g.beginPath();g.arc(x,y,23,0,Math.PI*2);g.fill();MVText(g,'!',x,y-19,true,34,'#fff',true);g.restore()}
function MVBodyWidth(b){return b.width==='narrow'?900:b.width==='medium'?1110:MVG.w}
function MVSetLayout(p){MVG.x=p.header==='profile'?213:146;MVG.w=p.header==='profile'?1300:1433}
function filasListaMov(g,texto,limite){
 const filas=[];let linea=[],ancho=0,espacio='';
 const agregar=(texto,negrita)=>{
  g.font=mvFont(negrita);
  const medida=g.measureText(texto).width;
  linea.push({texto,negrita,ancho:medida});ancho+=medida;
 };
 const terminar=()=>{if(linea.length)filas.push(linea);linea=[];ancho=0;espacio='';};
 for(const parte of texto.match(/\*\*[^*]+\*\*|[^*]+|\*/g)||[]){
  const negrita=parte.startsWith('**')&&parte.endsWith('**')&&parte.length>4;
  for(const token of (negrita?parte.slice(2,-2):parte).match(/\s+|\S+/g)||[]){
   if(!token.trim()){espacio=' ';continue;}
   g.font=mvFont(negrita);
   if(ancho && ancho+g.measureText(espacio+token).width>limite)terminar();
   if(espacio&&linea.length)agregar(espacio,negrita);
   espacio='';
   if(g.measureText(token).width<=limite)agregar(token,negrita);
   else {
    let tramo='';
    for(const letra of token) {
     if(tramo&&g.measureText(tramo+letra).width>limite){agregar(tramo,negrita);terminar();tramo='';}
     tramo+=letra;
    }
    if(tramo)agregar(tramo,negrita);
   }
  }
 }
 terminar();return filas;
}
const MVEsLista=b=>b.k==='list'||b.k==='box';
function MVFilasLista(g,b){
 if(b.filasLista)return b.filasLista;
 const ancho=(b.k==='box'?1320:1358)+(b.icon==='none'?39:0);
 return String(b.x||'').split('\n').filter(t=>t.trim()).map(texto=>({texto,lineas:filasListaMov(g,texto,ancho),marcador:true}));
}
const MVAltoElemento=(fila,espaciado)=>fila.lineas.length*MVG.line+espaciado.elemento;
function MVBlockLayout(g,b,y,paint=false,espaciado=MVEspaciadoBase){if(b.k==='page')return y;
 const x=MVG.x,W=MVBodyWidth(b),tx=b.x||'',title=String(b.t||'').trim(),begin=y;
 if(title&&b.k!=='note'){
  const tl=MVLines(g,title,W,true,MVG.head);
  tl.forEach(t=>{if(paint)MVText(g,t,x,y,true,MVG.head);y+=MVG.headLine});y+=espaciado.titulo;
 }
 if(b.k==='p'){const ls=MVLines(g,tx,W);ls.forEach(t=>{if(paint)MVText(g,t,x,y);y+=MVG.line});}
 else if(b.k==='facts'){for(const s of String(tx).split('\n').filter(s=>s.trim())){y=MVLine(g,s,x,y,W,paint);y+=espaciado.datos;}}
 else if(MVEsLista(b)){
  const filas=MVFilasLista(g,b);
  if(!filas.length)return title?y:begin;
  const isBox=b.k==='box',contentX=isBox?238:194,mode=b.icon||'check';
  const textX=mode==='none'?contentX-39:contentX;
  const alto=filas.reduce((s,fila)=>s+MVAltoElemento(fila,espaciado),0)+(isBox?espaciado.recuadro:0);
  let yy=y+(isBox?Math.floor(espaciado.recuadro/2)-1:0);
  if(paint&&isBox){g.strokeStyle='#bde6f7';g.lineWidth=2.4;g.strokeRect(122,y,1480,alto);}
  for(const fila of filas){
   if(paint&&fila.marcador&&mode==='check')MVCheck(g,contentX-48,yy+MVG.line/2);
   if(paint&&fila.marcador&&mode==='dot'){g.fillStyle=MVG.blue;g.beginPath();g.arc(contentX-48,yy+MVG.line/2,6,0,Math.PI*2);g.fill();}
   for(const linea of fila.lineas){
    if(paint){let xx=textX;for(const tramo of linea){MVText(g,tramo.texto,xx,yy,tramo.negrita);xx+=tramo.ancho;}}
    yy+=MVG.line;
   }
   yy+=espaciado.elemento;
  }
  y+=alto;
 }
 else if(b.k==='cards'){
  const cards=String(tx).split(/\n\s*\n/).map(str=>str.split('\n').filter(Boolean)).filter(a=>a.length);const gap=25,W2=(W-gap)/2;
  for(let i=0;i<cards.length;i+=2){const pair=cards.slice(i,i+2),widths=pair.length===1?[Math.min(990,W)]:[W2,W2],sizes=pair.map((card,j)=>{
   const cw=widths[j]-60,lines=[];card.forEach((line,n)=>lines.push(...MVLines(g,line,cw,n===0)));
   return {lines,h:58+lines.length*MVG.line+26};
  });const rh=Math.max(...sizes.map(s=>s.h));let xx=x;
   pair.forEach((card,j)=>{if(paint){g.strokeStyle='#c3e7f8';g.lineWidth=2.2;g.strokeRect(xx,y,widths[j],rh);let ly=y+30;card.forEach((line,n)=>{MVLines(g,line,widths[j]-60,n===0).forEach(t=>{MVText(g,t,xx+28,ly,n===0);ly+=MVG.line})})}xx+=widths[j]+gap});
   y+=rh+espaciado.tarjetas;
  }if(cards.length)y-=espaciado.tarjetas;
 }
 else if(b.k==='cta'){
  const lx=x+78,w=W-92,segments=String(tx).split('\n').filter(t=>t.trim());if(segments.length&&paint)MVPointer(g,x+25,y+24);
  segments.forEach(t=>{const lines=MVLines(g,t,w);lines.forEach((line,j)=>{if(paint)MVLine(g,line,lx,y,w,true,'#2586aa');y+=espaciado.accion})});
 }
 else if(b.k==='note'){
  const lx=x+79,w=W-100;
  const encabezado=MVLeerEtiqueta(tx.split('\n',1)[0])?.id==='note'&&title==='Nota:'?'':title;
  const nota=[encabezado,tx].filter(Boolean).join(' ');
  if(nota&&paint&&!b.continuacion)MVAlert(g,x+25,y+23);
  y=MVLine(g,nota,lx,y,w,paint,MVG.blue,encabezado);
 }
 return y;
}
function MVHeight(g,b,espaciado=MVEspaciadoBase){return MVBlockLayout(g,b,0,false,espaciado)}
function MVHeroInfo(g,p,compacto=false){const hasPhoto=p.heroMode==='photo'&&!!p.photo,tx=hasPhoto?590:150,w=hasPhoto?1010:1420;
 const title=String(p.heroTitle||'').trim(),intro=String(p.heroText||'').trim();
 const size=Math.min(63,Math.max(44,Math.round(63*Math.min(1,w/(Math.max(1,title.length)*35)))));
 const tls=MVLines(g,title,w,true,size),ils=MVLines(g,intro,w,false,39);
 const height=Math.max(hasPhoto?490:300,(compacto?125:169)+tls.length*70+(intro?28:0)+ils.length*47);
 return {hasPhoto,tx,w,size,tls,ils,height};
}
const MVFranjaCentrada=475, MVFranjaNormal=284;
function MVHeader(g,p,continuation=false,paint=false,franja){
 const isBanner=(p.header==='banner'||p.header==='profile')&&!continuation;
 const centered=p.header==='center'&&!continuation;
 const hb=franja??(centered?MVFranjaCentrada:MVFranjaNormal);
 if(isBanner){const headline=String(p.heroTitle||'').trim(),sub=String(p.heroText||'').trim(),titleSize=72,subSize=51;
  const tls=MVLines(g,headline,1450,true,titleSize),sls=MVLines(g,sub,1470,true,subSize);
  const bh=p.header==='profile'?Math.max(470,155+tls.length*81+30+sls.length*63+56):Math.max(470,110+tls.length*81+36+sls.length*63+83);
  if(paint){const grad=g.createLinearGradient(0,0,1725,0);grad.addColorStop(0,'#dbf1fb');grad.addColorStop(1,'#abe5fb');g.fillStyle=grad;g.fillRect(0,0,1725,bh);
   let yy=p.header==='profile'?155:(bh-(tls.length*81+(sls.length?30+sls.length*63:0)))/2;tls.forEach(t=>{MVText(g,t,862,yy,true,titleSize,MVG.blue,true);yy+=81});if(sls.length){yy+=30;sls.forEach(t=>{MVText(g,t,862,yy,true,subSize,MVG.blue,true);yy+=63})}}
  return bh+(p.header==='profile'?88:82);
 }
 if(paint){
  g.fillStyle='#003070';g.fillRect(0,0,1725,hb);
  // La cabecera de Movilidad Laboral usa la firma completa del arte de referencia.
  const logo=logosInstitucionales.adGobiernoAzul;
  const lw=centered?340:375,lh=lw*logo.h/logo.w;
  const yLogo=centered?74+(hb-MVFranjaCentrada)*.26:60;
  const yTexto=centered?344+(hb-MVFranjaCentrada)*.79:113;
  dibujarLogoInstitucional(g,logo,centered?862-lw/2:1570-lw,yLogo,lw,lh,'#fff');
  const texto=p.programTitle??MVNOMBRE,ancho=centered?1430:1000;
  g.font=mvFont(true,centered?52:51);
  const tamaño=(centered?52:51)*Math.min(1,ancho/Math.max(1,g.measureText(texto).width));
  MVText(g,texto,centered?862:151,yTexto,true,tamaño,'#fff',centered);
 }
 if(continuation||p.heroMode==='off'||!p.photo&&!p.heroTitle&&!p.heroText)return hb+114;
 const h=MVHeroInfo(g,p,franja!=null);if(paint){const grad=g.createLinearGradient(0,0,1725,0);grad.addColorStop(0,'#dcf1fb');grad.addColorStop(1,'#b5e4fa');g.fillStyle=grad;g.fillRect(0,hb,1725,h.height);
  if(h.hasPhoto){const yc=hb+h.height/2,im=p.photo;g.save();g.beginPath();g.arc(325,yc,197,0,Math.PI*2);g.clip();const s=Math.max(394/im.width,394/im.height),ww=im.width*s,hh=im.height*s;g.drawImage(im,325-ww/2,yc-197-(hh-394)*(p.photoY??50)/100,ww,hh);g.restore()}
  const textHeight=h.tls.length*70+(h.ils.length?28:0)+h.ils.length*47,yy0=hb+(h.height-textHeight)/2;let yy=yy0;
  h.tls.forEach(t=>{MVText(g,t,h.tx,yy,true,h.size);yy+=70});if(h.ils.length){yy+=28;h.ils.forEach(t=>{MVText(g,t,h.tx,yy);yy+=47})}
 }
 return hb+h.height+73;
}
function MVVisible(p){return p.blocks.filter(b=>b.k==='page'||String(b.x||'').trim()||(!b.ocultarVacio&&(b.t||'').trim()&&['p','list','box'].includes(b.k)));}
function MVSepararTexto(texto,cabe,cortes){
 let inferior=0,superior=cortes.length-1,corte=0;
 while(inferior<=superior){
  const medio=Math.floor((inferior+superior)/2);
  const limite=cortes[medio];
  if(cabe(texto.slice(0,limite).trimEnd())){corte=limite;inferior=medio+1;}
  else superior=medio-1;
 }
 return [texto.slice(0,corte).trimEnd(),texto.slice(corte).trimStart()];
}
function MVCortes(texto,patron=/\s+/gu){
 return Array.from(texto.matchAll(patron),m=>m.index).filter(i=>i>0);
}
function MVCortarPalabra(texto,cabe){
 let longitud=0;
 const cortes=Array.from(texto,letra=>(longitud+=letra.length));
 cortes.pop();
 return MVSepararTexto(texto,cabe,cortes);
}
function MVPartirTexto(g,b,espacio,paginaCompleta,espaciado){
 if(b.k==='note'&&MVHeight(g,b,espaciado)<=paginaCompleta)return [];
 const texto=String(b.x||'').trim();
 const cabe=x=>MVHeight(g,{...b,x},espaciado)<=espacio;
 const grupo=b.k==='facts'?/\n/gu:b.k==='cards'?/\n\s*\n/gu:/\s+/gu;
 let [inicio,resto]=MVSepararTexto(texto,cabe,MVCortes(texto,grupo));
 if(!inicio&&MVHeight(g,b,espaciado)>paginaCompleta){
  const primerGrupo=texto.split(grupo)[0];
  if(MVHeight(g,{...b,x:primerGrupo},espaciado)>paginaCompleta){
   [inicio]=MVSepararTexto(primerGrupo,cabe,MVCortes(primerGrupo));
   if(!inicio)[inicio]=MVCortarPalabra(primerGrupo,cabe);
   resto=texto.slice(inicio.length).trimStart();
  }
 }
 return inicio&&resto?[{...b,x:inicio},{...b,t:'',x:resto,continuacion:true}]:[];
}
function MVPartirLista(g,b,espacio,paginaCompleta,espaciado){
 const filas=MVFilasLista(g,b), margen=b.k==='box'?espaciado.recuadro:0;
 const cabecera=MVHeight(g,{...b,x:'',filasLista:[]},espaciado);
 let disponible=espacio-margen-cabecera;
 const caben=[];
 for(const [i,fila] of filas.entries()){
  const alto=MVAltoElemento(fila,espaciado);
  if(alto<=disponible){caben.push(fila);disponible-=alto;continue;}
  // Un elemento solo se divide si tampoco cabe entero en la página siguiente.
  const maximo=paginaCompleta-margen-(caben.length?0:cabecera);
  const lineas=Math.floor((disponible-espaciado.elemento)/MVG.line);
  const quedaron=filas.slice(i);
  if(alto>maximo&&lineas>0&&lineas<fila.lineas.length){
   const [inicio,resto]=[fila.lineas.slice(0,lineas),fila.lineas.slice(lineas)];
   const copiar=(parte,marcador)=>({lineas:parte,marcador,texto:parte.map(l=>l.map(t=>t.texto).join('')).join(' ')});
   caben.push(copiar(inicio,fila.marcador));quedaron[0]=copiar(resto,false);
  }
  if(!caben.length)return [];
  const bloque=(parte,t)=>({...b,t,filasLista:parte,x:parte.map(f=>f.texto).join('\n')});
  return [bloque(caben,b.t),bloque(quedaron,'')];
 }
 return [];
}
function MVPartirParaPagina(g,b,espacio,paginaCompleta,espaciado){
 if(MVEsLista(b))return MVPartirLista(g,b,espacio,paginaCompleta,espaciado);
 return MVPartirTexto(g,b,espacio,paginaCompleta,espaciado);
}
function MVLimite(p,continuacion){
 return continuacion?2040:p.header==='profile'?1975:p.header==='banner'?1840:2022;
}
function MVAlturaContenido(g,bloques,espaciado){
 return bloques.reduce((altura,b,i)=>altura+(i?espaciado.entre:0)+MVHeight(g,b,espaciado),0);
}

// Cada página guarda la misma composición que usan la vista previa y el PNG.
function MVPaginacion(p,espaciados=[],franjaInicial,aprovecharPortada=false){
 const g=cx,paginas=[];
 let blocks=[],inicio=MVHeader(g,p,false,false,franjaInicial),y=inicio,manual=false;
 const espaciado=()=>espaciados[paginas.length]||MVEspaciadoBase;
 const guardar=()=>paginas.push({
  perfil:p,blocks,espaciado:espaciado(),inicio,continuation:paginas.length>0,manual,
  franja:paginas.length?undefined:franjaInicial,desborde:y>MVLimite(p,paginas.length>0)+2
 });
 const cerrar=(porSalto=false)=>{
  guardar();blocks=[];inicio=MVHeader(g,p,true,false);y=inicio;manual=porSalto;
 };
 const añadir=(bloque,alto)=>{y+=(blocks.length?espaciado().entre:0)+alto;blocks.push(bloque);};
 for(const original of MVVisible(p)){
  if(original.k==='page'){
   if(blocks.length)cerrar(true);
   continue;
  }
  let pendiente=original;
  while(pendiente){
   const medidas=espaciado(),limite=MVLimite(p,paginas.length>0);
   const espacio=limite-y-(blocks.length?medidas.entre:0),alto=MVHeight(g,pendiente,medidas);
   if(alto<=espacio){añadir(pendiente,alto);break;}
   const maximoPagina=MVLimite(p,true)-MVHeader(g,p,true,false);
   const puedeRepartirse=MVEsLista(pendiente)?espacio>0:espacio>240;
   const partes=puedeRepartirse?MVPartirParaPagina(g,pendiente,espacio,maximoPagina,medidas):[];
   // Si ya hay una lista en la portada, lleva íntegra la siguiente cuando la mayoría
   // de sus elementos quedarían separados y puede caber entera en una página.
   const mejorJunta=!aprovecharPortada&&partes.length&&paginas.length===0&&MVEsLista(pendiente)&&blocks.some(MVEsLista)&&
    alto<=maximoPagina&&partes[0].filasLista.length<2;
   if(partes.length&&!mejorJunta){
    añadir(partes[0],MVHeight(g,partes[0],medidas));
    cerrar();pendiente=partes[1];
   }else if(blocks.length||!paginas.length)cerrar();
   else {añadir(pendiente,alto);break;}
  }
 }
 if(blocks.length||!paginas.length)guardar();
 return paginas;
}

function paginateMov(p){
 MVSetLayout(p);
 if(MVHeader(cx,p,false,false)>1770){
  // Las franjas de portada conservan su composición. El texto restante sigue en el cuerpo.
  const titulo=p.heroTitle.trim(),entrada=p.heroText.trim();
  const cabe=(heroTitle,heroText)=>MVHeader(cx,{...p,heroTitle,heroText},false,false)<=1770;
  const resto=[];
  if(!cabe(titulo,'')){
   let [primero,continuacion]=MVSepararTexto(titulo,t=>cabe(t,''),MVCortes(titulo));
   if(!primero)[primero,continuacion]=MVCortarPalabra(titulo,t=>cabe(t,''));
   p.heroTitle=primero;p.heroText='';
   resto.push(continuacion,entrada);
  }else{
   let [primero,continuacion]=MVSepararTexto(entrada,t=>cabe(titulo,t),MVCortes(entrada));
   if(!primero)[primero,continuacion]=MVCortarPalabra(entrada,t=>cabe(titulo,t));
   p.heroText=primero;
   resto.push(continuacion);
  }
  p.blocks=[...resto.filter(Boolean).map(x=>({k:'p',t:'',x})),...p.blocks];
 }
 const normal=MVPaginacion(p);
 const centradaConFoto=p.header==='center'&&p.heroMode==='photo'&&!!p.photo;
 return MVEquilibrarPortada(p,MVRecuperarCierre(p,normal,centradaConFoto));
}

// Aprovechar el espacio de la portada sin cambiar fuentes, texto ni orden.
function MVEquilibrarPortada(p,paginas){
 if(paginas.length<2||paginas.some(pagina=>pagina.manual||pagina.desborde)||MVVisible(p).some(b=>b.k==='page'))return paginas;
 const libre=pagina=>MVLimite(p,pagina.continuation)-pagina.inicio-MVAlturaContenido(cx,pagina.blocks,pagina.espaciado);
 const primera=paginas[0];
 if(libre(primera)>MVG.line*2){
  const alternativa=MVPaginacion(p,paginas.map(v=>v.espaciado),primera.franja,true);
  if(alternativa.length<=paginas.length&&alternativa.every(v=>!v.desborde)&&alternativa[0].blocks.length&&
   (alternativa.length<paginas.length||libre(alternativa[0])+MVG.line<libre(primera))){
   if(paginas.at(-1).cierreAjustado)alternativa.at(-1).cierreAjustado=paginas.at(-1).cierreAjustado;
   paginas=alternativa;
  }
 }
 // Distribuir una parte del aire sobrante entre apartados, sin estirarlos artificialmente.
 const portada=paginas[0], huecos=portada.blocks.length-1;
 if(huecos>0){
  const aumento=Math.max(0,Math.min(18,Math.floor((libre(portada)-MVG.line*.6)/huecos)));
  if(aumento)paginas[0]={...portada,espaciado:{...portada.espaciado,entre:portada.espaciado.entre+aumento}};
 }
 return paginas;
}

function MVRecuperarCierre(p,normal,centradaConFoto){
 if(normal.length!==3||MVVisible(p).some(b=>b.k==='page'))return normal;
 const [primera,segunda,ultima]=normal;
 if(!primera.blocks.length||!segunda.blocks.length||ultima.manual||normal.some(pagina=>pagina.desborde))return normal;
 const final=ultima.blocks.at(-1);
 const documentosYNota=centradaConFoto&&ultima.blocks.length===2&&
  ultima.blocks[0].hint==='documents'&&final?.k==='note'&&MVHeight(cx,ultima.blocks[0])<=MVG.line*6;
 if((ultima.blocks.length!==1&&!documentosYNota)||!final||MVHeight(cx,final)>MVG.line*5)return normal;

 const unidos=[...segunda.blocks,...ultima.blocks],limite=MVLimite(p,true);
 const cierreAjustado=documentosYNota?'Los documentos requeridos y la nota se acomodaron en la segunda página.':
  final.k==='note'?'La nota final se acomodó en la segunda página.':'El último apartado se acomodó en la segunda página.';
 // Mantener el reparto actual si reducir algunas separaciones de la segunda basta.
 for(const espaciado of [MVEspaciadoSuave,MVEspaciadoCompacto]){
  if(segunda.inicio+MVAlturaContenido(cx,unidos,espaciado)<=limite)
   return [primera,{...segunda,blocks:unidos,espaciado,cierreAjustado}];
 }
 // Antes de compactar, probar un reparto que aproveche la portada con los tamaños originales.
 const reparto=MVPaginacion(p,[],undefined,true);
 if(reparto.length===2&&reparto.every(v=>!v.desborde)){
  reparto[1].cierreAjustado=cierreAjustado;
  return reparto;
 }
 // Repartir de nuevo solo si el único bloque de la tercera era breve.
 for(const espaciado of [MVEspaciadoSuave,MVEspaciadoCompacto]){
  const ajuste=MVPaginacion(p,[espaciado,espaciado]);
  if(ajuste.length===2&&ajuste.every(pagina=>!pagina.desborde)){
   ajuste[1].cierreAjustado=cierreAjustado;
   return ajuste;
  }
 }
 if(centradaConFoto&&!normal.some(pagina=>pagina.manual)){
  // Para un cierre breve, conservar la cabecera centrada y compactar su espacio vertical.
  const espaciadoFinal={...MVEspaciadoCompacto,entre:18,elemento:6,recuadro:40};
  const ajuste=MVPaginacion(p,[MVEspaciadoCompacto,espaciadoFinal],365);
  if(ajuste.length===2&&ajuste.every(pagina=>!pagina.desborde)){
   ajuste[1].cierreAjustado=cierreAjustado;
   return ajuste;
  }
 }
 return normal;
}

async function drawM(K,plan,banda){
 const {perfil:p,blocks,continuation,espaciado,franja}=plan;
 MVSetLayout(p);
 const {c,g}=lienzoArte(1080,1350,K,banda);
 g.scale(1080/1725,1080/1725);
 g.fillStyle='#fff';g.fillRect(0,0,1725,2157);g.textBaseline='top';
 let y=MVHeader(g,p,continuation,true,franja);
 blocks.forEach((b,i)=>{
  if(i)y+=espaciado.entre;
  y=MVBlockLayout(g,b,y,true,espaciado);
 });
 c.desbordeEditorial=blocks.length?y>MVLimite(p,continuation)+2:y>2140;
 if((p.header==='banner'||p.header==='profile')&&!continuation){
  const logo=logosInstitucionales.cancilleria,lw=385,lh=lw*logo.h/logo.w;
  dibujarLogoInstitucional(g,logo,1210,p.header==='profile'?1800:1940,lw,lh,MVG.blue);
 }
 return c;
}

let versionVistaPrevia = 0;
async function prepararArtesVista(modo){
 if(modo==='dse')return [prepararDse()];
 if(modo==='ad')return esEditorialAD()?prepararEditorialAD():adAdmiteHistoria(adCur().v)?[prepararActividadAD(),prepararActividadAD(true)]:[prepararActividadAD()];
 if(modo==='sede')return prepararSede();
 if(modo==='mov'){
  const perfil={...MP(),blocks:MP().blocks.map(b=>({...b}))};
  const incompleto=!(perfil.heroTitle.trim()||perfil.heroText.trim()||MVVisible(perfil).some(b=>b.k!=='page'));
  return paginateMov(perfil).map((plan,i)=>({
   ...plan,nombre:'movilidad-laboral-pagina-'+(i+1)+'.png',ancho:1080,alto:1350,incompleto,
   dibujar:(K,banda)=>drawM(K,plan,banda)
  }));
 }
 return prepararArtesDui();
}

async function render(){
 if(!I)return false;
 const panel=$('out'), version=++versionVistaPrevia;
 try{
  const artes=await prepararArtesVista(M);
  const nuevasPaginas=[];
  for(const arte of artes){
   if(version!==versionVistaPrevia)return false;
   const canvas=await arte.dibujar(arte.escalaPrevia??1);
   try{
    if(version!==versionVistaPrevia)return false;
    if(canvas.desbordeEditorial)arte.desborde=true;
    nuevasPaginas.push(canvas.toDataURL('image/png'));
   }finally{canvas.width=canvas.height=0;}
  }
  if(version!==versionVistaPrevia)return false;
  pages=nuevasPaginas;pageSpecs=artes;
  panel.innerHTML=pages.map((u,i)=>{
   const rotulo='Vista previa, página '+(i+1)+(artes[i].tituloPagina?' · '+artes[i].tituloPagina:'');
   return '<figure><img src="'+u+'" alt="'+esc(rotulo)+'"><button type="button" data-sec-click="dl('+i+')">Descargar PNG'+
    (pages.length>1?' · página '+(i+1):'')+'</button></figure>';
  }).join('');
  panel.setAttribute('aria-busy','false');
  exteriorPreview();
  return true;
 }catch(error){
  if(version!==versionVistaPrevia)return false;
  console.error(error);
  pages=[];pageSpecs=[];panel.replaceChildren();panel.setAttribute('aria-busy','false');
  exteriorPreview();
  const estado=$('editorialEstado');
  estado.textContent='No se pudo actualizar la vista previa. Volver a abrir la plantilla.';
  estado.hidden=false;
  return false;
 }
}

 let previewActual=0, anchoPrevia=0;
 const carruselPrevia=$('out');
 function actualizarPaginaPrevia(indice) {
  const total=pages.length;
  previewActual=Math.min(Math.max(0,indice),Math.max(0,total-1));
  const titulo=pageSpecs[previewActual]?.tituloPagina;
  const rotulo=(previewActual+1)+' de '+total+(titulo?' · '+titulo:'');
  if($('previewPagina').textContent!==rotulo)$('previewPagina').textContent=rotulo;
  $('previewAnterior').disabled=previewActual===0;
  $('previewSiguiente').disabled=previewActual+1>=total;
 }
 function alinearPaginaPrevia(){
  anchoPrevia=carruselPrevia.clientWidth;
  if(!anchoPrevia)return;
  const destino=previewActual*anchoPrevia;
  if(Math.abs(carruselPrevia.scrollLeft-destino)>1)carruselPrevia.scrollLeft=destino;
 }
 function mostrarPaginaPrevia(indice){
  actualizarPaginaPrevia(indice);
  alinearPaginaPrevia();
 }
 function exteriorPreview() {
  const total=pages.length;
  const desborde=pageSpecs.some(arte=>arte.desborde);
  const faltaContenido=desborde||pageSpecs.some(arte=>arte.incompleto);
  $('editorialEstado').textContent = desborde ? (pageSpecs.find(arte=>arte.mensajeDesborde)?.mensajeDesborde || 'Reducir el texto. Si el diseño lo permite, distribuir la información en otra página.') :
   faltaContenido ? 'Agregue contenido al arte antes de descargar.' : avisoDatosEditoriales(pageSpecs)||pageSpecs.find(arte=>arte.cierreAjustado)?.cierreAjustado||'';
  $('editorialEstado').hidden=!$('editorialEstado').textContent;
  const soloHistoriaDesborda=desborde&&pageSpecs.every(a=>!a.incompleto&&(!a.desborde||a.historiaIlustrada));
  if(soloHistoriaDesborda)$('editorialEstado').textContent='El texto es demasiado largo para la historia. La publicación sigue disponible.';
  for(const [i,boton] of [...carruselPrevia.querySelectorAll('button')].entries())
   boton.disabled=faltaContenido&&(!soloHistoriaDesborda||!!pageSpecs[i]?.desborde);
  $('downloadAll').disabled=$('downloadZip').disabled=faltaContenido;
  $('previewNavegacion').hidden=$('downloadAll').hidden=$('downloadZip').hidden=total<2;
  carruselPrevia.tabIndex=total>1?0:-1;
  mostrarPaginaPrevia(previewActual);
 }
 $('previewAnterior').onclick=()=>mostrarPaginaPrevia(previewActual-1);
 $('previewSiguiente').onclick=()=>mostrarPaginaPrevia(previewActual+1);
 carruselPrevia.addEventListener('scroll',()=>{
  const ancho=carruselPrevia.clientWidth;
  if(!ancho)return;
  if(ancho!==anchoPrevia){alinearPaginaPrevia();return;}
  actualizarPaginaPrevia(Math.round(carruselPrevia.scrollLeft/ancho));
 });
 carruselPrevia.addEventListener('keydown',evento=>{
  if(evento.target!==carruselPrevia||pages.length<2||!['ArrowLeft','ArrowRight'].includes(evento.key))return;
  evento.preventDefault();
  mostrarPaginaPrevia(previewActual+(evento.key==='ArrowRight'?1:-1));
 });
 if(typeof ResizeObserver==='function')new ResizeObserver(alinearPaginaPrevia).observe(carruselPrevia);
 const selectorEfemeride=document.createElement('select');
 selectorEfemeride.id='efemerideDiseno';selectorEfemeride.hidden=true;
