 let editorAbierto=false, ultimoCampoEditado=null;
 // Historial interno para Atrás/Adelante en navegador, incluido el visor móvil.
 // Se conserva el URL del HTML, por lo que funciona como archivo local o estático.
 const marcaNavegacionGenerador='gpe-artes-2026';
 const estadoPantalla=(pantalla,datos={})=>({generador:marcaNavegacionGenerador,pantalla,...datos});
 let historialGeneradorDisponible=false;
 try{
  window.history.replaceState(estadoPantalla('inicio'),'');
  historialGeneradorDisponible=true;
 }catch(error){console.warn('Historial interno no disponible para este archivo.',error);}
 function registrarPantalla(pantalla,datos={}){
  if(!historialGeneradorDisponible)return;
  try{window.history.pushState(estadoPantalla(pantalla,datos),'');}
  catch(error){historialGeneradorDisponible=false;console.warn('No se pudo registrar la pantalla.',error);}
 }
 function retrocederPantalla(alternativa){
  if(historialGeneradorDisponible&&window.history.state?.generador===marcaNavegacionGenerador&&
   window.history.state.pantalla!=='inicio'&&window.history.length>1){
   window.history.back();
  }else alternativa();
 }
 function guardarPantallaActual(){
  if(!historialGeneradorDisponible||window.history.state?.generador!==marcaNavegacionGenerador)return;
  const actual=window.history.state;
  const datos=actual.pantalla==='editor'?{ruta:$('m').value,
   id:familiasExterior[$('m').value]?.selector?$(familiasExterior[$('m').value].selector).value:''}:
   (actual.pantalla==='inicio'||actual.pantalla==='sede'||actual.pantalla==='interno'||actual.pantalla==='catalogo')?{busqueda:buscarPlantillas.value}:{};
  try{window.history.replaceState({...actual,...datos},'');}catch(error){}
 }
 window.addEventListener('popstate',evento=>{
  const estado=evento.state;
  if(estado?.generador!==marcaNavegacionGenerador)return;
  if(estado.pantalla==='editor'){
   abrirEntradaCatalogo(estado.ruta||'efemerides',estado.id||'',[],false);
  }else if(estado.pantalla==='catalogo'){
    mostrarMapa(true);abrirCatalogoFamilia(estado.ruta,estado.id??null,false);
    buscarPlantillas.value=estado.busqueda||'';filtrarPlantillas();
   }else if(estado.pantalla==='sede'||estado.pantalla==='interno'){
   mostrarMapa(true);
   if(estado.pantalla==='interno')abrirSubmenuInterno(false);
   else abrirSubmenuSede(false);
   buscarPlantillas.value=estado.busqueda||'';
   filtrarPlantillas();
  }else{
   mostrarMapa(true);
   buscarPlantillas.value=estado.busqueda||'';
   filtrarPlantillas();
   $('tituloMapa').focus({preventScroll:true});
  }
 });

 function seleccionarDiseno(ruta,valor){
  const {selector,evento='change'}=familiasExterior[ruta];
  const control=$(selector);
  if(control.value===valor||![...control.options].some(opcion=>opcion.value===valor&&!opcion.disabled))return;
  control.value=valor;
  control.dispatchEvent(new Event(evento,{bubbles:true}));
 }

 function actualizarContextoEditor(){
  const ruta=$('m').value, familia=familiasExterior[ruta];
  const control=familia.selector?$(familia.selector):null;
  const ficha=catalogoPlantillas[ruta]?.[control?.value||''];
  const titulo=ficha?.nombre||control?.selectedOptions[0]?.textContent||familia.titulo||familia.nombre;
  $('editorTitulo').textContent=titulo;
  const categoriaSede=ruta==='mov'||(ruta==='atencion-consular'&&control?.value!=='individual');
  const nombreCategoria=categoriaSede?familiasExterior.sede.nombre:ruta==='esquelas'?familiasExterior.interno.nombre:familia.nombre;
  $('editorCategoria').textContent=nombreCategoria;
  $('editorCategoria').hidden=titulo===nombreCategoria;
  const opciones=control?[...control.options].filter(opcion=>!opcion.disabled&&
   (ruta!=='atencion-consular'||(control.value==='individual'?
    opcion.value==='individual':opcion.value!=='individual'))):[];
  disenosExterior.hidden=opciones.length<2;
  $('avisoDisenoExterior').hidden=ruta!=='ad';
  listaDisenos.replaceChildren(...opciones.map(opcion=>{
   const boton=document.createElement('button');
   boton.type='button';
   const presentacion=catalogoPlantillas[ruta]?.[opcion.value];
   if(presentacion)entradaCatalogo(boton,{nombre:presentacion.nombre,detalle:presentacion.detalle});
   else boton.textContent=opcion.textContent;
   if(opcion.selected)boton.setAttribute('aria-current','true');
   boton.onclick=()=>{
    seleccionarDiseno(ruta,opcion.value);
    disenosExterior.open=false;
    $('editorTitulo').focus({preventScroll:true});
   };
   return boton;
  }));
  mostrarVarianteCatalogo();
 }

