     function abrirFamiliaCatalogo(ruta){
    if(mapa.hidden)mostrarMapa(true);
    if(ruta==='sede')return abrirSubmenuSede();
    if(ruta==='interno')return abrirSubmenuInterno();
    if(ruta==='atencion-consular')return abrirCatalogoFamilia(ruta,'individual');
    return abrirCatalogoFamilia(ruta);
   }
   function abrirCatalogoFamilia(ruta,id=null,registrar=true){
    const fichas=catalogoPlantillas[ruta];if(!fichas)return;
    const ids=Object.keys(fichas).filter(id=>!(ruta==='ad'&&['independencia','invitacion-interna'].includes(id)));
    if(id===null&&ids.length===1)id=ids[0];
    const ficha=id===null?null:fichas[id];
    if(id!==null&&!ficha)return;
    const variantes=Object.keys(ficha?.variantes||{});
    if(ficha&&!variantes.length){abrirEntradaCatalogo(ruta,id,[],registrar);return;}
    if(registrar){guardarPantallaActual();registrarPantalla('catalogo',{ruta,id});}
    if(mapa.hidden)mostrarMapa(true);
    submenuSedeAbierto=true;submenuActual='catalogo';rutaSubmenuCatalogo=ruta;
    tituloSubmenuCatalogo=ficha?.nombre||familiasExterior[ruta].nombre;
    $('ramasMapa').hidden=true;resultadosPlantillas.hidden=true;subcategoriasSede.hidden=false;
    subcategoriasSede.setAttribute('aria-label',tituloSubmenuCatalogo);volverCategoriasSede.hidden=false;
    buscarPlantillas.value='';subcategoriasSede.replaceChildren();
    const agregar=(dato,accion)=>{const b=document.createElement('button');b.type='button';entradaCatalogo(b,dato);b.onclick=accion;subcategoriasSede.append(b);};
    if(ficha){
     for(const valor of variantes){const entrada=varianteCatalogo(ruta,id,valor);agregar(entrada,()=>abrirEntradaCatalogo(ruta,id,entrada.pasos));}
    }else{
     for(const key of ids){const f=fichas[key],v=Object.keys(f.variantes||{})[0];
      agregar({...f,miniatura:f.miniatura||varianteCatalogo(ruta,key,v)?.miniatura},()=>abrirCatalogoFamilia(ruta,key));}
    }
    filtrarPlantillas();window.scrollTo(0,0);$('tituloMapa').focus({preventScroll:true});
   }
function abrirSubmenuSede(registrar=true){
   submenuActual='sede';tituloSubmenuCatalogo='';rutaSubmenuCatalogo=null;
   subcategoriasSede.setAttribute('aria-label','Artes para sede');
   if(registrar){guardarPantallaActual();registrarPantalla('sede');}
   submenuSedeAbierto=true;
   $('ramasMapa').hidden=true;
   resultadosPlantillas.hidden=true;
   subcategoriasSede.hidden=false;
   buscarPlantillas.hidden=false;
   volverCategoriasSede.hidden=false;
   if(registrar)buscarPlantillas.value='';
   $('tituloMapa').textContent='Artes para sede';
   subcategoriasSede.replaceChildren();
   for(const [ruta,id] of [['sede','oficinas'],['mov',''],['atencion-consular','mixta']]){
    const ficha=catalogoPlantillas[ruta][id];
    const acceso=document.createElement('button');acceso.type='button';
    entradaCatalogo(acceso,ficha);
    acceso.onclick=()=>abrirCatalogoFamilia(ruta,id);
    subcategoriasSede.append(acceso);
   }
   filtrarPlantillas();
   $('tituloMapa').focus({preventScroll:true});
  }
  function abrirSubmenuInterno(registrar=true){
   if(registrar){guardarPantallaActual();registrarPantalla('interno');}
   submenuSedeAbierto=true;
   submenuActual='interno';tituloSubmenuCatalogo='';rutaSubmenuCatalogo=null;
    subcategoriasSede.setAttribute('aria-label','Artes de uso interno');
   $('ramasMapa').hidden=true;
   resultadosPlantillas.hidden=true;
   subcategoriasSede.hidden=false;
   buscarPlantillas.hidden=false;
   volverCategoriasSede.hidden=false;
   if(registrar)buscarPlantillas.value='';
   $('tituloMapa').textContent='Artes de uso interno';
   subcategoriasSede.replaceChildren();
   for(const id of ['invitacion-interna','firma','proyeccion','esquelas']){
    const ficha=id==='esquelas'?catalogoPlantillas.esquelas['']:catalogoPlantillas.interno[id];
    const acceso=document.createElement('button');
    acceso.type='button';
    entradaCatalogo(acceso,{...ficha,miniatura:id==='invitacion-interna'?'ad-invitacion-interna-v1':null});
    acceso.onclick=()=>abrirCatalogoFamilia(id==='esquelas'?'esquelas':'interno',id==='esquelas'?'':id);
    subcategoriasSede.append(acceso);
   }
   filtrarPlantillas();
   $('tituloMapa').focus({preventScroll:true});
  }
  for(const [ruta,{nombre,descripcion}] of Object.entries(familiasExterior)){
   if(ruta==='mov'||ruta==='esquelas')continue;
   const acceso=document.createElement('button');
   acceso.type='button';acceso.dataset.destino=ruta;
   entradaCatalogo(acceso,{nombre,detalle:descripcion});
   acceso.onclick=()=>abrirFamiliaCatalogo(ruta);
   $('ramasMapa').append(acceso);
  }

