function adArtworkBounds(transforms, shiftY = 0, shiftX = 0, escala = 1) {
  let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
  for (const [a, b, c, d, x, y] of transforms) {
    const e = x + shiftX, f = y + shiftY;
    const puntos = [[0,0],[1,0],[0,1],[1,1]];
    for (const [px, py] of puntos) {
      const X = a * px + c * py + e;
      const Y = b * px + d * py + f;
      if (X < minX) minX = X;
      if (Y < minY) minY = Y;
      if (X > maxX) maxX = X;
      if (Y > maxY) maxY = Y;
    }
  }
  const cx=(minX+maxX)/2, cy=(minY+maxY)/2;
  return {minX:cx+(minX-cx)*escala, minY:cy+(minY-cy)*escala,
    maxX:cx+(maxX-cx)*escala, maxY:cy+(maxY-cy)*escala,
    width:(maxX-minX)*escala, height:(maxY-minY)*escala, cx, cy};
}

function adPaintArtwork(g, image, transforms, shiftY, shiftX = 0, escala = 1) {
  // Escalar todas las piezas alrededor del centro del conjunto, no del lienzo.
  const caja=adArtworkBounds(transforms,shiftY,shiftX);
  for (const [a, b, c, d, x, y] of transforms) {
    g.save();
    if (escala!==1) {
      g.translate(caja.cx,caja.cy);
      g.scale(escala,escala);
      g.translate(-caja.cx,-caja.cy);
    }
    g.transform(a, b, c, d, x + shiftX, y + shiftY);
    g.drawImage(image, 0, 0, 1, 1);
    g.restore();
  }
}

let adLogoVersion = 0;
const adLogoUrls = new Set();

function adReleaseLogoUrls() {
  adLogoUrls.forEach(url => URL.revokeObjectURL(url));
  adLogoUrls.clear();
}

function adRemoveLogoMatte(logo) {
  const width = logo.naturalWidth, height = logo.naturalHeight;
  if (width < 8 || height < 8) return null;
  const canvas = document.createElement('canvas');
  canvas.width = width;
  canvas.height = height;
  const ctx = canvas.getContext('2d', {willReadFrequently: true});
  ctx.drawImage(logo, 0, 0);
  const frame = ctx.getImageData(0, 0, width, height);
  const pixels = frame.data;

  // Solo un margen blanco uniforme y conectado al exterior es un fondo recortable.
  const white = (pixel, min = 244) => {
    const p = pixel * 4, r = pixels[p], g = pixels[p + 1], b = pixels[p + 2];
    return pixels[p + 3] === 255 && Math.min(r, g, b) >= min && Math.max(r, g, b) - Math.min(r, g, b) <= 8;
  };
  const last = width * height - 1;
  if (![0, width - 1, last - width + 1, last].every(pixel => white(pixel))) return null;
  const inset = Math.max(1, Math.floor(Math.min(width, height) / 50));
  for (let i = 1; i < 16; i++) {
    const x = Math.floor((width - 1) * i / 16), y = Math.floor((height - 1) * i / 16);
    if (!white(inset * width + x) || !white((height - 1 - inset) * width + x) ||
        !white(y * width + inset) || !white(y * width + width - 1 - inset)) return null;
  }

  const count = width * height;
  const queue = new Uint32Array(count);
  let head = 0, tail = 0;
  function visit(pixel) {
    if (white(pixel, 239)) {
      pixels[pixel * 4 + 3] = 0;
      queue[tail++] = pixel;
    }
  }
  for (let x = 0; x < width; x++) {
    visit(x);
    visit(last - x);
  }
  for (let y = 1; y < height - 1; y++) {
    visit(y * width);
    visit(y * width + width - 1);
  }
  while (head < tail) {
    const pixel = queue[head++];
    const column = pixel % width;
    if (column > 0) visit(pixel - 1);
    if (column < width - 1) visit(pixel + 1);
    if (pixel >= width) visit(pixel - width);
    if (pixel + width < count) visit(pixel + width);
  }
  if (tail < count / 20 || tail >= count * .995) return null;

  // Descontamina el antialias alrededor del recorte sin borrar los blancos interiores.
  for (let i = 0; i < tail; i++) {
    const pixel = queue[i];
    const column = pixel % width;
    const neighbours = [];
    if (column > 0) neighbours.push(pixel - 1);
    if (column < width - 1) neighbours.push(pixel + 1);
    if (pixel >= width) neighbours.push(pixel - width);
    if (pixel + width < count) neighbours.push(pixel + width);
    for (const n of neighbours) {
      const p = n * 4;
      if (pixels[p + 3] !== 255) continue;
      const low = Math.min(pixels[p], pixels[p + 1], pixels[p + 2]);
      if (low < 208) continue;
      const alpha = Math.min(254, Math.round((255 - low) * 255 / 50));
      for (let c = 0; c < 3; c++) {
        pixels[p + c] = 255 - (255 - pixels[p + c]) * 255 / alpha;
      }
      pixels[p + 3] = alpha;
    }
  }
  ctx.putImageData(frame, 0, 0);
  return canvas;
}

async function adLoadLogos(files) {
  const version = ++adLogoVersion;
  const loaded = [], urls = [];
  try {
    for (const file of files) {
      let url = URL.createObjectURL(file);
      urls.push(url);
      let logo = new Image();
      logo.src = url;
      await logo.decode();
      if (version !== adLogoVersion) return;
      let cleaned = null;
      try { cleaned = adRemoveLogoMatte(logo); } catch (_) {}
      if (cleaned) {
        const blob = await new Promise(resolve => cleaned.toBlob(resolve, 'image/png'));
        if (version !== adLogoVersion) return;
        if (blob) {
          const transparent = new Image();
          const cleanUrl = URL.createObjectURL(blob);
          urls.push(cleanUrl);
          transparent.src = cleanUrl;
          await transparent.decode();
          URL.revokeObjectURL(url);
          url = cleanUrl;
          logo = transparent;
        }
      }
      loaded.push({logo, url});
    }
    if (version !== adLogoVersion) return;
    adReleaseLogoUrls();
    LG.ad = loaded.map(item => item.logo);
    loaded.forEach(item => adLogoUrls.add(item.url));
    renderLogoLists();
    go();
  } catch (error) {
    if (version===adLogoVersion) throw error;
  } finally {
    urls.filter(url => !adLogoUrls.has(url)).forEach(url => URL.revokeObjectURL(url));
  }
}
