 g.drawImage(fondo,fondo.width*crop,0,fondo.width*(1-crop),fondo.height,w*.6384,h*.1284,w*.3616,h*.7431);
 const centro=w/2,tinta='#111E60';
 const lineas=representacion.map(s=>String(s||'').trim()).filter(Boolean);
 const estilo=(f,weight,s)=>({f,w:weight,s,c:tinta,i:0});
 const caja={x:W*.20,y:0,w:W*.60,h:0,in:[0,0,0,0],an:'t',lf:1.21};
