// Distribución opcional de colaboradores para las cuatro variantes navideñas.
// Mantener una fila siempre que sea legible; utilizar dos únicamente si mejoran la escala.
function navidadDistribuirLogos(logos,z){
 const gap=.20, rowGap=.10;
 const proporciones=logos.map(l=>Math.max(.01,(l.naturalWidth||l.width)/(l.naturalHeight||l.height)));
 function plan(grupos){
  const maxH=(z.h-rowGap*(grupos.length-1))/grupos.length;
  const filas=grupos.map(indices=>{
   const suma=indices.reduce((a,i)=>a+proporciones[i],0);
   const h=Math.min(maxH,(z.w-gap*(indices.length-1))/suma);
   const w=suma*h+gap*(indices.length-1);
   return {indices,h,w};
  });
  const alto=filas.reduce((a,f)=>a+f.h,0)+rowGap*(filas.length-1);
  let y=z.y+(z.h-alto)/2;
  const rects=[];
  for(const f of filas){
   let x=z.x+(z.w-f.w)/2;
   for(const i of f.indices){const w=proporciones[i]*f.h;rects.push({i,x,y,w,h:f.h});x+=w+gap;}
   y+=f.h+rowGap;
  }
  return {rects,minH:Math.min(...filas.map(f=>f.h))};
 }
 if(!logos.length)return [];
 const indices=logos.map((_,i)=>i);
 let mejor=plan([indices]);
 if(logos.length>=3){
  const corte=Math.ceil(logos.length/2), alterna=plan([indices.slice(0,corte),indices.slice(corte)]);
  if(alterna.minH>mejor.minH*1.12)mejor=alterna;
 }
 return mejor.rects;
}
