const sedeVersionCompuesta = {id:'v8v9',nombre:'Oficinas en El Salvador (con mapa)',partes:[
 {id:'v8',titulo:'Mapa con oficinas'},{id:'v9',titulo:'Directorio de oficinas'}
]};
