 const esCartelera = diseño === 'cartelera';
 const formato = $('sedeFormato');
 const soloPost = esCartelera && sedeVersionActiva() === 'consulados';
 const permiteX=esCartelera&&!soloPost;
 const opcionX=formato.querySelector('[value="x"]');
 opcionX.hidden=opcionX.disabled=!permiteX;
 if(!permiteX&&formato.value==='x')formato.value='post';
 if (diseño === 'firma' || diseño === 'prensa') { montarUcomSede(diseño); return; }
 formato.querySelector('[value="historia"]').disabled = soloPost;
 if (soloPost && formato.value === 'historia') formato.value = 'post';
 $('sedePanelColores').hidden = esCartelera;
 $('sedeColorRestaurar').hidden = esCartelera;
 $('sedeTextoRestaurar').hidden = esCartelera;
 $('sedePaletaAleatoria').hidden = esCartelera;
 $('sedePaletaDeshacer').hidden = esCartelera;
 if (esCartelera) {
  $('sedePanelFoto').hidden = true;
  montarCartelera(sedeVersionActiva());
  return;
 }
 const {version, plantilla, estado} = seleccionSede();
 $('sedePaleta').value = estado.paleta ?? 'original';
 if($('sedePaleta').selectedIndex<0)$('sedePaleta').value='';
 $('sedePaletaDeshacer').hidden = !estado.colorAnterior;
 const campos = plantilla.campos.map(([id, titulo, , multilinea]) => {
  const etiqueta = '<label for="sede-' + id + '">' + titulo + '</label>';
  const editor = multilinea ? '<textarea id="sede-' + id + '" rows="3" maxlength="400"></textarea>' :
   '<input id="sede-' + id + '" type="text" maxlength="200">';
  return '<div>' + etiqueta + editor + '</div>';
 });
 const directorioEnColumnas = ['v2','v10','v11'].includes(version);
 const grupos = directorioEnColumnas
  ? [...campos.slice(24),...oficinasDirectorio.map((_, i) => '<details class="sede-oficina"' + (i === 0 ? ' open' : '') + '><summary id="sedeResumenOficina-' +
   (i + 1) + '"></summary>' + campos.slice(4 * i, 4 * i + 4).join('') + '</details>')]
  : version === 'v9'
   ? oficinasDirectorioDoble.map((_, i) => '<details class="sede-oficina"' + (i === 0 ? ' open' : '') + '><summary id="sedeResumenOficina-' +
    (i + 1) + '"></summary>' + campos.slice(3 * i, 3 * i + 3).join('') + '</details>')
   : campos;
 $('sedeCampos').innerHTML = grupos.join('');
 plantilla.campos.forEach(([id]) => {
  const campo = $('sede-' + id);
  campo.value = estado.texto[id];
  campo.oninput = () => {
   estado.texto[id] = campo.value;
   if ((directorioEnColumnas || version === 'v9') && /^oficina[1-6]$/.test(id)) actualizarResumenSede(id, estado);
   go();
  };
 });
 if (directorioEnColumnas || version === 'v9') for (let i = 1; i <= 6; i++) actualizarResumenSede('oficina' + i, estado);
 const coloresVisibles = Object.entries(plantilla.colores).filter(([id]) => !(('v8' === version || 'v9' === version) && id === 'icono'));
 $('sedeColores').innerHTML = coloresVisibles.map(([id]) =>
  '<label class="sede-color" for="sedeColor-' + id + '">' + nombresColoresSede[id] +
  '<input id="sedeColor-' + id + '" type="color"></label>').join('');
 Object.keys(plantilla.colores).forEach(id => {
  const campo = $('sedeColor-' + id);
  if(!campo)return;
  campo.value = estado.color[id];
  const logoFijo=diseño==='oficinas'&&id==='logo';
  if(logoFijo){campo.disabled=true;campo.title='Color automático según el fondo.';}
  campo.oninput = () => {
   if(logoFijo){campo.value=estado.color.logo=logoRegionalSede(estado.color,version);return;}
   estado.color[id] = campo.value;
   if(diseño==='oficinas'&&(id==='fondo'||id==='secundario')){
    estado.color.logo=logoRegionalSede(estado.color,version);
    const campoLogo=$('sedeColor-logo');if(campoLogo)campoLogo.value=estado.color.logo;
   }
    estado.paleta='';$('sedePaleta').value='';
   if ((version === 'v8' || version === 'v9') && id === 'flecha') actualizarColorFlechasDobleSede(campo.value);
   if ((version === 'v8' || version === 'v9') && id === 'marcador') actualizarColorMarcadoresDobleSede(campo.value);
   go();
  };
 });
 $('sedePanelFoto').hidden = !plantilla.foto;
 $('sedeFoto').value = '';
