const trazadosSede = Object.fromEntries(Object.entries(trazadosSedeTexto).map(([k,items])=>[k,items.map(path=>new Path2D(path))]));
function dibujarTrazadoSede(g,clave,x,y,ancho) {
 g.save();g.translate(x,y);g.scale(ancho/1000,ancho/1000);
 for (const trazado of trazadosSede[clave]) g.fill(trazado);
 g.restore();
}
function sedeFirma(g, x, y, ancho, color, conGobierno = true) {
 const logo = conGobierno ? firmaSedeGobierno : firmaSedeEscudo;
 g.save();g.translate(x,y);g.scale(ancho/logo.w,ancho/logo.w);g.fillStyle=color;
 dibujarTrazadoSede(g,...logo.marca);
 g.fillRect(...logo.separador);
 dibujarTrazadoSede(g,'ministerio',...logo.leyenda);
 g.restore();
}

function sedeFotoFondo(g, foto, alto, encuadre) {
 if (!foto) return;
 const escala = Math.max(1080/foto.naturalWidth, alto/foto.naturalHeight);
 const w = foto.naturalWidth*escala, h = foto.naturalHeight*escala;
 g.save();
 g.beginPath();
 g.rect(0,0,1080,alto);
 g.clip();
 g.drawImage(foto,(1080-w)*encuadre.x/100,(alto-h)*encuadre.y/100,w,h);
 g.restore();
}
function sedeFotoReferencia(g,foto,alto,encuadre) {
 if(!foto)return;
 const zoom=1+Math.max(Math.abs(encuadre.x-50),Math.abs(encuadre.y-50))*.0012;
 const ancho=1080*zoom, altura=alto*zoom;
 g.drawImage(foto,(1080-ancho)*encuadre.x/100,(alto-altura)*encuadre.y/100,ancho,altura);
}
function sedeDegradado(g, desde, hasta, color) {
 const gr = g.createLinearGradient(0,desde,0,hasta);
 gr.addColorStop(0,color + '00');
 gr.addColorStop(.55,color + 'b8');
 gr.addColorStop(1,color);
 g.fillStyle = gr;
 g.fillRect(0,desde,1080,hasta-desde+1);
}

function distribuirSede(bloques,arriba,abajo) {
 if(!bloques.length)return [];
 const altura=bloques.reduce((total,b)=>total+b.alto,0);
 const separacion=bloques.slice(1).reduce((total,b)=>total+(b.gap??12),0);
 const factor=Math.max(0,Math.min(1,(abajo-arriba-altura)/Math.max(1,separacion)));
 const espacios=bloques.map((b,i)=>i?(b.gap??12)*factor:0);
 const topes=[];
 let limite=abajo;
 for(let i=bloques.length-1;i>=0;i--){
  topes[i]=limite-bloques[i].alto;
  limite=topes[i]-espacios[i];
 }
 let y=arriba;
 return bloques.map((b,i)=>{
  const top=Math.max(y+espacios[i],Math.min(topes[i],b.centro-b.alto/2));
  y=top+b.alto;
  return top;
 });
}

function pintarFlujoSede(g,bloques,arriba,abajo) {
 const activos=bloques.filter(b=>b.alto>0);
 const posiciones=distribuirSede(activos,arriba,abajo);
 if(activos.length&&posiciones.at(-1)+activos.at(-1).alto>abajo+.5)g.desbordeEditorial=true;
 g.save();g.beginPath();g.rect(0,arriba,1080,abajo-arriba+1);g.clip();
 activos.forEach((b,i)=>b.pintar(posiciones[i]));
 g.restore();
}

function bloqueTextoSede(g,valor,centro,opciones) {
 const {x=540,width=950,weight=400,family,align='center',color,gap,maxLineas=2,tracking=0}=opciones;
 let {size}=opciones;
 const medir=()=>{
  g.font=sedeFuente(size,weight,family);
  return lineasEditorial(g,valor,width);
 };
 let filas=medir();
 const minimo=size*.66;
 while(filas.length>maxLineas&&size>minimo){size--;filas=medir();}
 if(filas.length>maxLineas)g.desbordeEditorial=true;
 const paso=size*1.11, alto=filas.length*paso;
 return {alto,centro,gap,pintar(top){
  filas.forEach((f,i)=>sedeLinea(g,f,x,top+(i+.5)*paso,{size,weight,family,align,color,width,tracking}));
 }};
}

function bloqueRotuloSede(g,texto,centro,c,{x=540,ancho,alto,radio,size,margen,gap}) {
 const valor=String(texto??'').trim();
 if(!valor)return {alto:0};
 const disponible=ancho-2*margen, sizeOriginal=size;
 g.save();
 g.textAlign='center';g.textBaseline='middle';
 const medir=()=>{
  g.font=sedeFuente(size,900);
  return lineasEditorial(g,valor,disponible);
 };
 g.font=sedeFuente(size,900);
 const anchoLinea=g.measureText(valor).width;
 if(!valor.includes('\n')&&anchoLinea>disponible&&anchoLinea<=disponible/.92){
  size=size*(disponible-1)/anchoLinea;
 }
 let filas=medir();
 const minimo=sizeOriginal*.70;
 while(filas.length>2&&size>minimo){size=Math.max(minimo,size-1);filas=medir();}
 const desborde=filas.length>2||filas.some(f=>g.measureText(f).width>disponible+.1);
 if(desborde)g.desbordeEditorial=true;
 filas=filas.slice(0,2);
 const fuente=g.font, paso=size*1.12;
 const altura=alto+(filas.length-1)*paso;
 g.restore();
 return {alto:altura,centro,gap,pintar(top){
  g.save();
  sedeCaja(g,x-ancho/2,top,ancho,altura,radio,c.caja);
  if(desborde){
   g.clip();
  }
  g.fillStyle=c.cajaTexto;g.font=fuente;
  g.textAlign='center';g.textBaseline='middle';
  filas.forEach((linea,i)=>{
   const m=g.measureText(linea);
   const ajuste=(m.actualBoundingBoxAscent-m.actualBoundingBoxDescent)/2||0;
   g.fillText(linea,x,top+altura/2+(i-(filas.length-1)/2)*paso+ajuste);
  });
  g.restore();
 }};
}

function bloqueListaSede(g,t,c,opciones) {
 const {arriba,abajo,centro=arriba,gap,...resto}=opciones;
 return sedeListaOficinas(g,t,c,{arriba,abajo,...resto,comoBloque:{centro,gap}});
}

function bloqueSeparadorSede(g,centro,color,ancho,alto,gap) {
 return {centro,alto,gap,pintar:y=>sedeSeparador(g,y,color,ancho,alto)};
}


function sedeListaOficinas(g, t, c, opciones) {
 const {tipo, arriba, abajo, paso, size, icono, espacio=18, peso=300, familia, pinOriginal=false, escalaMinima=.66} = opciones;
 const ancho=Math.min(opciones.ancho,780);
 const nombres = Array.from({length:6}, (_,i) => String(t['oficina'+(i+1)] || '').trim()).filter(Boolean);
 if (!nombres.length) return {alto:0};
 g.save();
 g.textAlign='left';
 g.textBaseline='middle';
 function componer(escala) {
  const fuente = size*escala, pin = icono*escala, sangria = pin + espacio*escala;
  const disponible=ancho-sangria, interlinea=fuente*1.15;
  g.font=sedeFuente(fuente,peso,familia);
  const filas=nombres.map(nombre => {
   // Un nombre compuesto puede ocupar otra línea sin cambiar de proporciones.
   const lineas=[];
   for (const linea of wrap(g,protegerToponimos(nombre),disponible)) {
    if (g.measureText(linea).width <= disponible || linea.includes('\u00a0')) { lineas.push(linea); continue; }
    let parte='';
    for (const letra of linea) {
     if (parte && g.measureText(parte+letra).width > disponible) { lineas.push(parte); parte=''; }
     parte+=letra;
    }
    if (parte) lineas.push(parte);
   }
   return {lineas, alto:Math.max(pin,lineas.length*interlinea)};
  });
  const separacion=Math.max(2,(paso-Math.max(icono,size*1.15))*escala);
  const alto=filas.reduce((s,f)=>s+f.alto,0)+separacion*(filas.length-1);
  const texto=Math.min(disponible,Math.max(...filas.flatMap(f=>f.lineas.map(l=>g.measureText(l).width))));
  return {filas,pin,sangria,interlinea,separacion,alto,texto,fuente};
 }
 const altoDisponible=abajo-arriba;
 let bloque=componer(1);
 if (bloque.alto>altoDisponible&&bloque.separacion>2) {
  const separacion=Math.max(2,bloque.separacion-(bloque.alto-altoDisponible)/Math.max(1,nombres.length-1));
  bloque.alto-=(bloque.separacion-separacion)*(nombres.length-1);
  bloque.separacion=separacion;
 }
 if (bloque.alto>altoDisponible) {
  let menor=escalaMinima, mayor=1;
  if(componer(menor).alto>altoDisponible)g.desbordeEditorial=true;
  for (let i=0; i<12; i++) {
   const media=(menor+mayor)/2;
   if (componer(media).alto<=altoDisponible) menor=media; else mayor=media;
  }
  bloque=componer(menor);
 }
 const {filas,pin,sangria,interlinea,separacion,alto,texto,fuente}=bloque;
 const x=(1080-sangria-texto)/2;
 g.restore();
 const pintar=top=>{
 g.save();g.textAlign='left';g.textBaseline='middle';
 let y=top;
 g.font=sedeFuente(fuente,peso,familia);
 for (const fila of filas) {
  const centro=y+fila.alto/2, pinY=centro-pin/2;
  if (pinOriginal && c.icono===disenosSede.oficinas.v7.colores.icono && pinRecortadoSede.complete && pinRecortadoSede.naturalWidth) {
   const w=pin*pinRecortadoSede.naturalWidth/pinRecortadoSede.naturalHeight;
   g.drawImage(pinRecortadoSede,x+(pin-w)/2,pinY,w,pin);
  } else {
   dibujarIconoSede(g,tipo,x,pinY,pin,c.icono);
  }
  g.fillStyle=c.texto;
  fila.lineas.forEach((linea,k) => g.fillText(linea,x+sangria,centro+(k-(fila.lineas.length-1)/2)*interlinea,ancho-sangria));
  y+=fila.alto+separacion;
 }
 g.restore();
 };
 if(opciones.comoBloque)return {alto,centro:opciones.comoBloque.centro+alto/2,gap:opciones.comoBloque.gap,pintar};
 pintar(arriba+Math.max(0,(abajo-arriba-alto)*.27));
}

function dibujarResumenSede(g,H,t,c,pinOriginal=false) {
 const historia=H===1920;
 const base=historia?{firma:275,ancho:440,titulo:614,sub:720,regla:816,
  horario:908,paso:66,reglaDos:1123,lista:1169,fila:78,size:46,icono:58}:
  {firma:146,ancho:345,titulo:414,sub:498,regla:574,
   horario:644,paso:52,reglaDos:815,lista:860,fila:61,size:36,icono:47};
  sedeFondoCurvoSuperior(g,c.secundario,H);
  // Las variantes con fotografía/recorte mantienen su composición autorizada.
  sedeFirma(g,(1080-base.ancho)/2,base.firma-(pinOriginal?0:historia?27:18),base.ancho,c.logo);
  const w=historia?636:502, regla=historia?5:4;
  const arriba=historia?520:347, abajo=historia?1730:1282;
  if(pinOriginal){
   pintarFlujoSede(g,[
    bloqueRotuloSede(g,t.titulo,base.titulo,c,{
     ancho:historia?886:698,alto:historia?104:82,radio:historia?39:24,size:historia?74:58,margen:historia?24:21
    }),
    bloqueTextoSede(g,t.subtitulo,base.sub,{size:historia?73:58,weight:900,color:c.titulo}),
    bloqueSeparadorSede(g,base.regla,c.texto,w,regla,16),
    bloqueTextoSede(g,t.horarioTitulo,base.horario,{size:base.size,weight:900,color:c.acento}),
    bloqueTextoSede(g,t.horario,base.horario+base.paso,{size:base.size,weight:300,color:c.texto,gap:5}),
    bloqueTextoSede(g,t.nota,base.horario+2*base.paso,{size:base.size,weight:300,color:c.texto,gap:5}),
    bloqueSeparadorSede(g,base.reglaDos,c.texto,w,regla,15),
    bloqueListaSede(g,t,c,{tipo:'pin',arriba:base.lista,abajo:abajo+70,paso:base.fila,size:base.size,
     ancho:918,icono:base.icono,pinOriginal,gap:18})
   ],arriba,abajo);
   return;
  }
  // v1 «Horarios y ubicaciones»: medir las líneas reales antes de colocar los
  // bloques, para que 1, 3 o 6 oficinas no dependan de desplazamientos fijos.
  const inicio=historia?485:305, final=historia?1800:1278;
  const titulo=bloqueRotuloSede(g,t.titulo,base.titulo,c,{
   ancho:historia?886:698,alto:historia?104:82,radio:historia?39:24,size:historia?74:58,margen:historia?24:21
  });
  const bloques=[
   titulo,
   bloqueTextoSede(g,t.subtitulo,base.sub,{size:historia?73:58,weight:900,color:c.titulo}),
   bloqueSeparadorSede(g,base.regla,c.texto,w,regla,16),
   bloqueTextoSede(g,t.horarioTitulo,base.horario,{size:base.size,weight:900,color:c.acento}),
   bloqueTextoSede(g,t.horario,base.horario+base.paso,{size:base.size,weight:300,color:c.texto,gap:5}),
   bloqueTextoSede(g,t.nota,base.horario+2*base.paso,{size:base.size,weight:300,color:c.texto,gap:5}),
   bloqueSeparadorSede(g,base.reglaDos,c.texto,w,regla,15)
  ];
  const separaciones=historia?[0,25,43,40,8,7,46,36]:[0,18,29,26,5,5,36,27];
  const alturaCabecera=bloques.reduce((s,b)=>s+b.alto,0);
  const espacios=separaciones.slice(1).reduce((s,n)=>s+n,0);
  const disponibleLista=Math.max(120,final-inicio-alturaCabecera-espacios);
  const lista=bloqueListaSede(g,t,c,{
   tipo:'pin',arriba:0,abajo:disponibleLista,paso:base.fila,size:base.size,
   ancho:918,icono:base.icono,escalaMinima:.52,gap:18
  });
  bloques.push(lista);
  const altoTotal=alturaCabecera+espacios+lista.alto;
  // El centro óptico se calcula con la altura real del listado; el encabezado
  // conserva su relación con el logotipo y el conjunto nunca se empuja al pie.
  const centro=historia?1090:734;
  const inicioOptico=Math.min(historia?610:420,Math.max(inicio,centro-altoTotal/2));
  if(inicioOptico+altoTotal>final+.5)g.desbordeEditorial=true;
  let y=inicioOptico;
  for(let i=0;i<bloques.length;i++){
   y+=separaciones[i];
   const bloque=bloques[i];
   if(bloque.alto>0)bloque.pintar(y);
   y+=bloque.alto;
  }
}

