const faltaLogoEsquela = d => d.tipoLogo==='personalizado'&&!d.logo;
function dibujarLogotipoCargado(g,logo,x,y,w,h){
 const escala=Math.min(w/logo.width,h/logo.height);
 const ancho=logo.width*escala, alto=logo.height*escala;
 g.drawImage(logo,x+(w-ancho)/2,y+(h-alto)/2,ancho,alto);
}
function logoEsquela(g,d,x,y,w,h,color) {
 const tipo=d.tipoLogo||'original';
 if (tipo==='original') return false;
 if (tipo==='personalizado') {
  if(!d.logo)return false;
  dibujarLogotipoCargado(g,d.logo,x,y,w,h);
 } else if(tipo==='gobierno') {
  const ancho=Math.min(w,h*.8);
  g.fillStyle=color;dibujarTrazadoSede(g,'gobierno',x+(w-ancho)/2,y,ancho);
 } else {
  const ancho=Math.min(w,h*2.32);
  sedeFirma(g,x+(w-ancho)/2,y,ancho,color,false);
 }
 return true;
}
