 const summary=document.createElement('summary');summary.textContent='Pegar desde un documento';
 const ayuda=document.createElement('p');ayuda.className='field-help';ayuda.textContent='Separar las convocatorias con «ARTE 1», «ARTE 2», etc. Se creará un formulario por arte.';
