 lista.forEach((arte,i)=>{const lugar=arte.jornadasSvp?.[0]?.representacion?.replace(/^Consulado General de El Salvador en\s*/i,'')||'';
  selector.add(new Option('Arte '+(i+1)+(lugar?' · '+lugar.slice(0,44):''),String(i)));});
 selector.value=String(actual);selector.onchange=()=>{raiz.svpSeleccion=Number(selector.value);montarEditorialAD(false);go();};label.append(selector);contenedor.append(label);
 const barra=document.createElement('div');barra.className='svp-acciones-artes';
 const boton=(nombre,accion,deshabilitado=false)=>{const b=document.createElement('button');b.className='g';b.type='button';b.textContent=nombre;b.disabled=deshabilitado;b.onclick=()=>{accion();montarEditorialAD(false);go();};barra.append(b);};
 boton('Crear arte',()=>{lista.push(svpNuevoArte());raiz.svpSeleccion=lista.length-1;});
