 boton('Bajar',()=>{[lista[actual],lista[actual+1]]=[lista[actual+1],lista[actual]];raiz.svpSeleccion=actual+1;},actual===lista.length-1);
 boton('Quitar arte',()=>{if(!confirm('¿Eliminar el arte '+(actual+1)+'?'))return;lista.splice(actual,1);if(!lista.length)lista.push(svpNuevoArte());raiz.svpSeleccion=Math.min(actual,lista.length-1);},false);
 contenedor.append(barra);panel.append(contenedor);
