 function medir(texto,font){g.font=font;return lineasEditorial(g,texto,marcoSvp.anchoEtiquetas);}
 const lineasIntro=medir(intro,'600 30px '+montserratSvp);
 const lineasCiudad=medir(ciudad,'700 31px '+poppinsSvp);
 const tituloOriginal=!datos.svpTitulo||/^(?:Programa de Servicios)?\s*[«"“]?El Salvador\+/i.test(datos.svpTitulo.replace(/^Programa de Servicios\s+/i,''));
 const tituloPersonalizado=tituloOriginal?[]:medir(datos.svpTitulo,'700 40px '+poppinsSvp);
