 const marcaRef=n===1?334.95:n===2?239.34:Math.max(56,239.34-(n-2)*79);
 const yEtiquetasRef=n===1?564:n===2?523:Math.max(305,523-(n-2)*64);
 const yTarjetasRef=n===1?798:n===2?776:Math.max(550,776-(n-2)*75);
 const nFilas=filas.length;
 // Con una fila se conserva el mismo margen izquierdo y no se deja un hueco de dos filas.
