   const {tipo,item}=entrada;
   const primera=i===0;
   let pos;
   if(primera)pos=tipo==='etiqueta'?Math.max(marca+altoEncabezado+31,yEtiquetas+trasladar):Math.max(marca+altoEncabezado+47,yTarjetas+trasladar);
