function dibujarIconoContactoUcom(g,nombre,x,y,dim,tinta=ucomAzul) {
 const icono=iconosContactoUcom[nombre];
 if(!icono)return false;
 const {ancho,alto,trazado}=icono;
 const escala=dim*((nombre==='pin'||nombre==='lugar')?0.94:0.92)/Math.max(ancho,alto);
 g.save();
 // Mantener la geometría original con centro óptico estable, incluso en íconos apaisados.
 g.translate(x+(dim-ancho*escala)/2,y+(dim-alto*escala)/2);
 g.scale(escala,escala);
 g.fillStyle=tinta;
 g.fill(trazado,'evenodd');
 g.restore();
 return true;
}

const datosUcom = texto => String(texto || '').trim();
// Los datos recomendados se revisan en la interfaz. Solo se bloquea una
// pieza sin contenido editorial usable (un escudo o rótulo genérico no basta).
function revisarCamposEditoriales(datos,campos,contenido){
 return {incompleto:!contenido.some(id=>datosUcom(datos[id])),
  revisar:campos.filter(([id])=>!datosUcom(datos[id])).map(([,nombre])=>nombre)};
}
function avisoDatosEditoriales(artes){
 const pendientes=[...new Set(artes.flatMap(a=>a.revisar||[]))];
 if(!pendientes.length)return '';
 const lista=new Intl.ListFormat('es',{style:'long',type:'conjunction'}).format(pendientes);
 return 'Puede descargar el arte con los datos disponibles. Revise si debe completar: '+lista+'.';
}

