const ESQUELA_LAZOS={
 canciller:{sil:new Path2D('M1089 1223 L1079 1224 L1073 1227 L1055 1243 L1045 1257 L1042 1265 L1041 1275 L1040 1276 L1040 1302 L1041 1303 L1041 1312 L1042 1313 L1043 1322 L1035 1329 L984 1365 L980 1370 L979 1412 L1048 1361 L1050 1361 L1052 1366 L1052 1370 L1068 1446 L1096 1413 L1096 1409 L1094 1404 L1093 1395 L1091 1390 L1091 1386 L1089 1381 L1088 1372 L1086 1367 L1085 1358 L1080 1338 L1092 1328 L1113 1306 L1121 1293 L1125 1276 L1122 1247 L1118 1238 L1108 1229 L1099 1225 L1090 1224 Z M1078 1247 L1079 1248 L1088 1249 L1098 1253 L1104 1257 L1112 1265 L1112 1268 L1097 1283 L1073 1301 L1071 1297 L1068 1276 L1067 1275 L1066 1249 L1071 1247 Z'),front:new Path2D('M1071 1232 L1066 1235 L1049 1253 L1044 1263 L1044 1266 L1042 1270 L1042 1277 L1041 1278 L1041 1302 L1042 1303 L1042 1312 L1044 1320 L1044 1328 L1069 1446 L1073 1443 L1097 1414 L1090 1378 L1086 1364 L1085 1355 L1083 1350 L1080 1329 L1078 1324 L1074 1302 L1072 1299 L1071 1289 L1068 1277 L1067 1250 L1071 1249 L1071 1245 L1070 1244 Z')},
 superior:{sil:new Path2D('M610 121 L604 124 L600 129 L593 144 L590 155 L591 167 L594 176 L602 193 L606 198 L606 201 L577 246 L577 248 L587 277 L621 223 L624 226 L656 275 L666 246 L635 200 L642 187 L648 171 L650 163 L649 149 L643 135 L635 124 L626 120 Z M608 140 L618 139 L619 138 L629 139 L638 144 L632 159 L621 177 L617 174 L603 149 L602 144 Z'),front:new Path2D('M600 134 L597 138 L592 152 L592 167 L598 184 L600 186 L611 208 L621 223 L625 227 L656 275 L658 275 L658 272 L666 250 L666 245 L637 203 L635 198 L623 180 L620 178 L611 164 L603 147 L604 142 L602 139 L601 134 Z')}
};
function marcoEsquela(g,formato,vector){
 if(vector&&vector.complete&&vector.naturalWidth){
  // Geometría UCOM 1080 × 1350, escalada al lienzo interno equivalente 1215 × 1518.
  // El archivo contiene trazos SVG, rectángulos, lazos y sombreado del pliegue.
  g.drawImage(vector,0,0,1215,1518);
 }else{
  // Evitar exportar un arte sin marco si falla la decodificación del SVG.
  g.desbordeEditorial=true;
 }
}
function renglonesEsquela(g,valor,ancho,tam,familia,peso,maxLineas,minTam){
 const contenido=String(valor??'').replace(/\r\n?/g,'\n').trim();
 if(!contenido)return {lineas:[],tam,paso:tam*1.28,alto:0,exceso:false};
 let lineas=[],ajustado=tam;
 function dividir(){
  g.font=peso+' '+ajustado+'px '+familia;
  const resultado=[];
  for(const parrafo of contenido.split('\n')){
   if(!parrafo.trim()){resultado.push('');continue;}
   let renglon='';
   for(const palabra of parrafo.trim().split(/\s+/)){
    const probar=renglon?renglon+' '+palabra:palabra;
    if(g.measureText(probar).width<=ancho){renglon=probar;continue;}
    if(renglon){resultado.push(renglon);renglon='';}
    if(g.measureText(palabra).width<=ancho){renglon=palabra;continue;}
    // Dividir palabras extraordinariamente largas en vez de deformar las letras.
    let trozo='';
    for(const caracter of palabra){
     if(trozo&&g.measureText(trozo+caracter).width>ancho){resultado.push(trozo);trozo='';}
     trozo+=caracter;
    }
    renglon=trozo;
   }
   if(renglon)resultado.push(renglon);
  }
  while(resultado.length&&!resultado[resultado.length-1])resultado.pop();
  return resultado;
 }
 for(;ajustado>=minTam;ajustado-=1){lineas=dividir();if(lineas.length<=maxLineas)break;}
 if(ajustado<minTam){ajustado=minTam;lineas=dividir();}
 const paso=ajustado*1.28;
 return {lineas,tam:ajustado,paso,alto:lineas.length*paso,exceso:lineas.length>maxLineas};
}
function dibujarEsquelaInstitucional(g,d,formato,vector){
 g.save();g.scale(1080/1215,1350/1518);
 g.fillStyle='#f3f3f3';g.fillRect(0,0,1215,1518);
 marcoEsquela(g,formato,vector);
 const campos=[
  {id:'texto1',ancho:625,tam:31,min:21,fuente:L,peso:300,max:5,asc:31},
  {id:'nombre',ancho:690,tam:65,min:43,fuente:ucomSerif,peso:400,max:3,asc:61},
  {id:'qddg',ancho:700,tam:43,min:27,fuente:ucomSerif,peso:400,max:2,asc:39},
  {id:'texto2',ancho:665,tam:31,min:21,fuente:L,peso:300,max:6,asc:30},
  {id:'fecha',ancho:790,tam:27,min:20,fuente:L,peso:300,max:3,asc:26}
 ];
 const textos={...d,qddg:d.qddg===undefined?'Q.D.D.G.':d.qddg};
 const bloques=campos.map(c=>({...c,...renglonesEsquela(g,textos[c.id],c.ancho,c.tam,c.fuente,c.peso,c.max,c.min)}));
 // Aire editorial original entre los cinco elementos y la línea bajo el nombre.
 const distancia=[47,19,44,39,45],reglaAlto=2.5;
 let alto=bloques.reduce((a,b)=>a+b.alto,0)+distancia.reduce((a,b)=>a+b,0)+reglaAlto;
 const escala=Math.min(1,735/Math.max(1,alto));
 if(escala<.70||bloques.some(b=>b.exceso))g.desbordeEditorial=true;
 const x=607.5,centroY=758.5;
 let y=centroY-(alto*escala)/2;
 g.translate(x,y);g.scale(escala,escala);
 y=0;g.fillStyle='#262626';g.textAlign='center';g.textBaseline='alphabetic';
 for(let k=0;k<bloques.length;k++){
  const b=bloques[k];
  g.font=b.peso+' '+b.tam+'px '+b.fuente;
  for(const [n,linea] of b.lineas.entries()){
   if(linea)g.fillText(linea,0,y+b.asc*b.tam/b.tam+n*b.paso);
  }
  y+=b.alto;
  if(k===1){
   y+=distancia[1];
   // Ajustar la línea a la anchura visible del nombre sin perder el largo mínimo de referencia.
   g.font=b.peso+' '+b.tam+'px '+b.fuente;
   const anchoNombre=Math.max(0,...b.lineas.map(l=>g.measureText(l).width));
   const regla=Math.min(350,Math.max(280,anchoNombre*.53));
   g.fillStyle='#424242';g.fillRect(-regla/2,y,regla,reglaAlto);
   g.fillStyle='#262626';
   y+=reglaAlto+distancia[2];
  }else if(k===0)y+=distancia[0];
  else if(k===2)y+=distancia[3];
  else if(k===3)y+=distancia[4];
 }
 g.restore();
}


async function prepararFirmaUcom() {
 const d={...datosEditoriales('firma-ucom')};
 await fuentesEditorial();
 const revision=revisarCamposEditoriales(d,[['nombre','nombre'],['cargo','cargo'],['correo','correo institucional'],
  ['sede','sede o representación']],['nombre','cargo','correo','sede','telefono','celular','direccion']);
 return arteEditorial('firma-correo.png',1626,540,revision,g=>{
  g.fillStyle='#fff';g.fillRect(0,0,1626,540);
  g.fillStyle='#111e60';dibujarTrazadoSede(g,'gobierno',38,103,276);
  g.fillStyle=ucomAzul;g.fillRect(359,48,2,444);
  const x=405, ancho=1173;
  textoUcom(g,d.nombre,x,48,ancho,62,{alineacion:'left',peso:700,familia:F,maximo:73});
  textoUcom(g,d.cargo,x,120,ancho,35,{alineacion:'left',peso:700,familia:F,maximo:82});
  const telefonos=[['Teléfono',d.telefono],['Celular',d.celular],['Correo',d.correo]].filter(([,v])=>datosUcom(v));
  telefonos.forEach(([k,v],i)=>textoUcom(g,k+': '+v,x,204+i*42,ancho,35,{alineacion:'left',maximo:43}));
  textoUcom(g,d.sede,x,369,ancho,35,{alineacion:'left',peso:700,familia:F,maximo:44});
  textoUcom(g,d.direccion,x,413,ancho,35,{alineacion:'left',maximo:98});
 });
}
// Referencia gráfica principal de las cuatro variantes de prensa:
// https://github.com/julieatpeace/generator (formatos y css/styles.css).
// Las medidas tipográficas se conservan; el bloque completo se centra según
// su altura visible. El selector corto/largo continúa siendo manual.
const prensaReferencia={
 fuentes:[['Bembo oficial',400],['Bembo oficial',700],['Museo Sans oficial',900],['Museo Sans oficial',500]],
 lista:false,fuentesCargadas:new Set(),fondo:null,escudo:null,promesa:null
};
// Recursos de prensa originales de GitHub, incrustados para uso sin conexión.
// Se conserva el PNG original y el SVG con la geometría y el color originales.
const prensaRecursosOriginales = {"fondo":__recursosNetlify[59],"escudo":__recursosNetlify[60]};
function prensaCargarImagen(uri){
 return new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>reject(new Error('Recurso de prensa no disponible'));img.src=uri;});
}
function prensaCargarRecursos(){
 if(prensaReferencia.promesa)return prensaReferencia.promesa;
 prensaReferencia.promesa=(async()=>{
  await Promise.allSettled(prensaReferencia.fuentes.map(async([alias,peso])=>{
   const caras=await document.fonts.load(`${peso} 24px "${alias}"`,'Comunicado de prensa ÁÉÍÓÚÑ');
   if(caras.some(c=>c.status==='loaded'))prensaReferencia.fuentesCargadas.add(`${alias}:${peso}`);
  }));
  const imagenes=await Promise.allSettled([prensaCargarImagen(prensaRecursosOriginales.fondo),prensaCargarImagen(prensaRecursosOriginales.escudo)]);
  if(imagenes[0].status==='fulfilled')prensaReferencia.fondo=imagenes[0].value;
  if(imagenes[1].status==='fulfilled')prensaReferencia.escudo=imagenes[1].value;
  prensaReferencia.lista=prensaReferencia.fuentesCargadas.size===4&&!!prensaReferencia.fondo&&!!prensaReferencia.escudo;
  return prensaReferencia.lista;
 })();
 return prensaReferencia.promesa;
}
// Composición aislada de la interfaz. Se reproduce la estructura de tabla,
// los porcentajes, márgenes de párrafo, saltos y tamaños del HTML original.
// El navegador mide cada palabra en el mismo bloque que se exporta a Canvas.
function medirComunicado(d,largo,convocatoria=false){
 const W=1275,H=1650,anchoTitulo=W*(largo?.65:.60),ancho=W*(largo?.75:.68);
 const host=document.createElement('div');
 host.style.cssText='position:fixed;left:-20000px;top:0;width:1275px;height:1650px;visibility:hidden;pointer-events:none;';
 const raiz=host.attachShadow({mode:'open'});
 raiz.innerHTML=`<style>
 :host{all:initial;position:fixed;left:-20000px;top:0;visibility:hidden;pointer-events:none}
 .papel{width:1275px;height:1650px;font-family:"Times New Roman",serif;font-size:16px;line-height:normal;box-sizing:content-box;color:black}
 .tabla{width:100%;display:table;border-spacing:0}
 .celda{width:${largo?75:80}%;display:table-cell;text-align:center}
 header{display:block;font:inherit}
 .marca{display:inline-block;width:${largo?10:15}%;aspect-ratio:1062.6/870.4;vertical-align:baseline}
 .representacion{color:#111e60;font-family:${tipografiaFirmaInstitucional};font-size:${largo?'16pt':'150%'};font-weight:400}
 p{display:block;margin:1em auto;white-space:pre-line;line-height:normal;color:#000;font-weight:400}
 .rotulo{font-family:"Bembo oficial","Bembo institucional",Georgia,serif;font-size:${largo?'30px':'25pt'};font-weight:700;letter-spacing:3px}
 .titulo{width:${largo?65:60}%;font-family:"Museo Sans oficial","Museo Sans",sans-serif;font-size:${largo?'18pt':'22pt'};font-weight:900}
 .cuerpo,.fecha{width:${largo?75:68}%;font-family:"Museo Sans oficial",MuseoL,sans-serif;font-size:${largo?'14pt':'18pt'};font-weight:500}
 .cuerpo{text-align:justify;text-justify:inter-word}.fecha{text-align:right}
 </style><div class="papel"><div class="tabla"><div class="celda"><header><span class="marca"></span><br><br><span class="representacion r1"></span><br><span class="representacion r2"></span></header><center><br>${largo?'':'<br>'}<p class="rotulo"></p><p class="titulo"></p><p class="cuerpo"></p><p class="fecha"></p></center></div></div></div>`;
 const papel=raiz.querySelector('.papel');
 for(const [selector,valor] of [['.r1',String(d.repre1||'').toLocaleUpperCase('es')],['.r2',String(d.repre2||'').toLocaleUpperCase('es')],['.rotulo',convocatoria?'CONVOCATORIA DE PRENSA':'COMUNICADO DE PRENSA'],['.titulo',d.titulo],['.cuerpo',d.cuerpo],['.fecha',d.fecha]]){
  raiz.querySelector(selector).textContent=String(valor||'').replace(/\r\n?/g,'\n');
 }
 document.body.append(host);
 try{
  const base=papel.getBoundingClientRect(),marca=raiz.querySelector('.marca').getBoundingClientRect();
  const logo={x:marca.left-base.left,y:marca.top-base.top,w:marca.width,h:marca.height};
  const textos=[];let desborde=false;
  for(const selector of ['.r1','.r2','.rotulo','.titulo','.cuerpo','.fecha']){
   const el=raiz.querySelector(selector),st=getComputedStyle(el),t=el.firstChild;if(!t||t.nodeType!==Node.TEXT_NODE)continue;
   const rango=document.createRange();
   // La posición de cada palabra incluye la justificación inter-word real
   // del navegador y respeta los saltos de línea de la plantilla original.
   for(const m of t.data.matchAll(/[^\s]+/gu)){
    rango.setStart(t,m.index);rango.setEnd(t,m.index+m[0].length);
    const rect=rango.getBoundingClientRect();if(!rect.width||!rect.height)continue;
    const palabra={texto:m[0],x:rect.left-base.left,y:rect.top-base.top,w:rect.width,h:rect.height,
      font:`${st.fontWeight} ${st.fontSize} ${st.fontFamily}`,color:st.color,tracking:parseFloat(st.letterSpacing)||0};
    textos.push(palabra);
    if(palabra.x<-.5||palabra.x+palabra.w>W+.5)desborde=true;
    if(['.titulo','.cuerpo','.fecha'].includes(selector)){
     const caja=el.getBoundingClientRect();if(rect.left<caja.left-.5||rect.right>caja.right+.5)desborde=true;
    }
   }
  }
  // Desplazar juntos el escudo y los textos: el espacio entre título y
  // cuerpo, los saltos manuales y la justificación mantienen su posición relativa.
  let inicio=logo.y,fin=logo.y+logo.h;
  for(const t of textos){inicio=Math.min(inicio,t.y);fin=Math.max(fin,t.y+t.h);}
  const margen=72,holgura=H-2*margen-(fin-inicio);
  if(holgura<-.5)desborde=true;
  // Leve compensación óptica hacia arriba, sin rebasar el margen superior.
  const sobrante=Math.max(0,holgura);
  const ajuste=margen+sobrante/2-Math.min(24,sobrante*.08)-inicio;
  logo.y+=ajuste;
  for(const t of textos)t.y+=ajuste;
  const fecha=raiz.querySelector('.fecha').getBoundingClientRect();
  const cuerpo=raiz.querySelector('.cuerpo').getBoundingClientRect();
  return {ancho,anchoTitulo,tam:largo?14*4/3:24,tamTitulo:largo?24:22*4/3,desborde,
   plan:{logo,textos,ySello:logo.y,yFecha:fecha.top-base.top+ajuste,altoCuerpo:cuerpo.height}};
 }finally{host.remove();}
}
function documentoDePrensaEnUnaPagina(d,largo,convocatoria,revision){
 const {plan,desborde}=medirComunicado(d,largo,convocatoria);
 const arte=arteEditorial((convocatoria?'convocatoria':'comunicado')+'-de-prensa-'+(largo?'largo-':'corto-')+'1.png',1275,1650,revision,ctx=>{
  ctx.fillStyle='#eeeff0';ctx.fillRect(0,0,1275,1650);
  if(prensaReferencia.fondo){
   ctx.drawImage(prensaReferencia.fondo,0,0,1275,1650);
  }else{ctx.fillStyle='#e2e5ed';dibujarTrazadoInstitucional(ctx,'escudo',669,289,1040);}
  const {x,y,w,h}=plan.logo;
  if(prensaReferencia.escudo)ctx.drawImage(prensaReferencia.escudo,x,y,w,h);
  else{
   ctx.fillStyle='#111e60';const emblema=w*.67;
   dibujarTrazadoSede(ctx,'escudoUna',x+(w-emblema)/2,y,emblema);
   ctx.fillRect(x,y+h-0.5,w,Math.max(.5,w*2.4/1062.6));
  }
  ctx.textAlign='left';ctx.textBaseline='alphabetic';
  for(const t of plan.textos){
   ctx.font=t.font;ctx.fillStyle=t.color;
   if('letterSpacing' in ctx)ctx.letterSpacing=t.tracking+'px';
   const met=ctx.measureText(t.texto),asc=met.fontBoundingBoxAscent??t.h*.78,desc=met.fontBoundingBoxDescent??t.h*.22;
   const baseline=t.y+(t.h-asc-desc)/2+asc;
   if(!('letterSpacing' in ctx)&&t.tracking){let px=t.x;for(const c of t.texto){ctx.fillText(c,px,baseline);px+=ctx.measureText(c).width+t.tracking;}}
   else ctx.fillText(t.texto,t.x,baseline);
  }
  if('letterSpacing' in ctx)ctx.letterSpacing='0px';
 });
 if(desborde){
  arte.desborde=true;
  arte.mensajeDesborde=largo?'El contenido supera el espacio del formato largo. Reducir el texto antes de descargar.':(!medirComunicado(d,true,convocatoria).desborde?'El contenido supera el espacio del formato corto. Seleccionar «'+(convocatoria?'Convocatoria larga':'Comunicado largo')+'» o reducir el texto.':'El contenido supera el espacio de ambos formatos. Reducir el texto antes de descargar.');
 }
 return [arte];
}
async function prepararPrensaUcom(version){
 const d={...datosEditoriales(claveDatosPrensa(version))};
 const largo=version.includes('largo')||version.includes('larga');
 const revision=revisarCamposEditoriales(d,[['repre1','representación'],['titulo','título'],
  ['cuerpo','texto'],['fecha','fecha de emisión']],['titulo','cuerpo']);
 await Promise.all([fuentesEditorial(),prensaCargarRecursos()]);
 return documentoDePrensaEnUnaPagina(d,largo,version.includes('convocatoria'),revision);
}

const tonosCartelera = {fondo:'#f1f4fd', azul:'#003e83', claro:'#43a3ee', blanco:'#ffffff', logo:'#102754'};
let imagenContraportada;

function lineasPegadasCartelera(texto) {
 const textoLimpio=String(texto||'').replace(/^\uFEFF/,'').replace(/\r\n?|[\u000b\u2028\u2029]/g,'\n')
  .replace(/&#(?:x([0-9a-f]{1,6})|(\d{1,7}));/gi,(original,hex,dec)=>{
   const n=hex?parseInt(hex,16):Number(dec);
   return n>0&&n<=0x10ffff?String.fromCodePoint(n):original;
  })
  .replace(/&nbsp;/gi,' ').replace(/&amp;/g,'&');
 return textoLimpio.split('\n').map(l=>l.replace(/\u00a0/g,' ').trim()
  .replace(/^>\s?/, '').replace(/\\+$/, '').trim()
  .replace(/^(?:#{1,6}\s+|[-•]\s+)/,'')
  .replace(/^(?:\*\*|__)(.+?)(?:\*\*|__)$/,'$1').trim()).filter(Boolean);
}
function fechaDePortadaCartelera(registros) {
 const valores=[...new Set(registros.map(r=>r.fecha.trim()).filter(Boolean))];
 if(valores.length<=1)return valores[0]||'';
 const parsear=valor=>{
  const m=/^(.+?)\s+de\s+(enero|febrero|marzo|abril|mayo|junio|julio|agosto|septiembre|setiembre|octubre|noviembre|diciembre)\s+(?:de|del)\s+(\d{4})\.?$/i.exec(valor);
  if(!m)return null;
  const rango=m[1].toLocaleLowerCase('es').replace(/\b(?:lunes|martes|mi[eé]rcoles|jueves|viernes|s[áa]bado|domingo)\b/g,'').trim();
  const partes=/^(\d{1,2})(?:\s*(y|al?|hasta|[-–])\s*(\d{1,2}))?$/i.exec(rango);
  if(!partes)return null;
  const d=Number(partes[1]),f=Number(partes[3]||partes[1]),mes=m[2].toLocaleLowerCase('es').replace('setiembre','septiembre');
  const i=['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'].indexOf(mes);
  if(d<1||f<d||f>new Date(Date.UTC(Number(m[3]),i+1,0)).getUTCDate())return null;
  return {mes,ordinal:i,year:m[3],dias:partes[2]?.toLowerCase()==='y'?[d,f]:Array.from({length:f-d+1},(_,i)=>d+i)};
 };
 const interpretadas=valores.map(parsear);
 if(interpretadas.some(r=>!r))return '';
 const meses=new Map();
 for(const r of interpretadas){
  const clave=r.year+'-'+String(r.ordinal).padStart(2,'0');
  if(!meses.has(clave))meses.set(clave,{...r,dias:new Set()});
  for(const d of r.dias)meses.get(clave).dias.add(d);
 }
 const lista=new Intl.ListFormat('es',{type:'conjunction'});
 const anios=new Set(interpretadas.map(r=>r.year));
 const incluirAnio=anios.size>1;
 const rangos=[...meses.keys()].sort().map(clave=>{
  const {dias,mes,year}=meses.get(clave);
  const ds=[...dias].sort((a,b)=>a-b),ultimo=ds.at(-1);
  const etiqueta=ds.length>2&&ultimo-ds[0]+1===ds.length
   ? ds[0]+' al '+ultimo : lista.format(ds.map(String));
  return etiqueta+' de '+mes+(incluirAnio?' de '+year:'');
 });
 return lista.format(rangos)+(incluirAnio?'':' de '+interpretadas[0].year);
}

function importarListadoCartelera(texto, version) {
  const lineas=lineasPegadasCartelera(texto);
  if(!lineas.length)throw Error('Pegar primero el texto de las jornadas o los consulados móviles.');
  const registros=[], fechas={jornada:'',consulado:''}, gruposDeSede=[];
  const fechasExplicitas=new WeakSet();
  let grupoSede=null;
  let tipo='',fecha='',region='',actual=null,ultimoCampo='';
  const esRepresentacion=t=>/^(?:Consulado(?:\s+General)?|Embajada|Misi[oó]n|Representaci[oó]n|Secci[oó]n\s+Consular|Agencia\s+Consular)\b/i.test(t);
  const esHorario=t=>/^\d{1,2}\s*:\s*\d{2}(?:\s*(?:a\.?\s*m\.?|p\.?\s*m\.?|m\.?))?/i.test(t);
  const encabezadoTipo=/^(Jornadas?\s+extraordinarias?|Consulados?\s+m[oó]viles?)\s+(?:del?|para|[-–:])\s*(.+)$/i;
  const regionConocida=/^(?:Estados\s+Unidos|M[eé]xico|Canad[aá]|Centroam[eé]rica|Suram[eé]rica|Sudam[eé]rica|Europa|Asia|Australia|Ocean[ií]a|[AÁ]frica|Caribe|Norteam[eé]rica|Am[eé]rica\s+Central|Am[eé]rica\s+del\s+Sur|Am[eé]rica\s+del\s+Norte)$/i;
  const etiquetas=/^(Lugar|Direcci[oó]n|Hora|Horario(?: de atenci[oó]n)?|Fecha|Ubicaci[oó]n|Ciudad|Servicio|Tr[aá]mite|Informaci[oó]n adicional|Observaciones?|Nota|Requisitos?)\s*:\s*(.*)$/i;
  const notaSinRotulo=/^(?:cupo(?:s)?\s+(?:limitad|disponib)|por orden de llegada\b|atenci[oó]n\s+(?:por|con|sin)\b|entrada\s+(?:libre|gratuita)\b|llevar\b|presentar\b|se requiere\b)/i;
  const aumentar=(clave,valor)=>{
   if(!valor)return;
   actual[clave]=(actual[clave]?actual[clave]+(clave==='detalle'?'\n':' '):'')+valor;
   ultimoCampo=clave;
  };
  for(const [numero,contenido] of lineas.entries()){
   const enc=encabezadoTipo.exec(contenido);
   if(enc){
    tipo=/^jornada/i.test(enc[1])?'jornada':'consulado';
    if(version==='consulados'&&tipo!=='consulado')
     throw Error('Este texto incluye jornadas extraordinarias. Para importar ambas actividades, seleccionar «Cartelera de jornadas y consulados».');
    fecha=enc[2].trim();region='';actual=null;ultimoCampo='';
    if(!fechas[tipo])fechas[tipo]=fecha;
    continue;
   }
   const regionExplicita=/^(?:Regi[oó]n|Pa[ií]s)\s*:\s*(.+)$/i.exec(contenido);
   const sigueRepresentacion=esRepresentacion(lineas[numero+1]||'');
   if(actual&&notaSinRotulo.test(contenido)){
    aumentar('detalle',contenido);continue;
   }
   if(actual&&ultimoCampo==='fecha'&&!actual.fecha&&!esRepresentacion(contenido)&&
      !esHorario(contenido)&&!regionConocida.test(contenido)&&!etiquetas.test(contenido)){
    actual.fecha=contenido;ultimoCampo='';continue;
   }
   const regionInferida=actual?.horario&&sigueRepresentacion&&
    !esRepresentacion(contenido)&&!/^(?:Para|Lugar|Direcci[oó]n|Servicio|Tr[aá]mite)\b/i.test(contenido)&&
    !/[\d,:;.]/.test(contenido)&&contenido.split(/\s+/).length<=4;
   if(regionExplicita||regionConocida.test(contenido)||regionInferida||
      (!actual&&tipo&&!esRepresentacion(contenido)&&!esHorario(contenido)&&!etiquetas.test(contenido))){
    if(!tipo)throw Error('Indicar primero el tipo de actividad y la fecha. Revisar la línea '+(numero+1)+'.');
    region=(regionExplicita?regionExplicita[1]:contenido).replace(/[.\s]+$/,'').trim();
    actual=null;ultimoCampo='';
    continue;
   }
   if(esRepresentacion(contenido)){
    if(!tipo)throw Error('Falta el encabezado de jornadas o consulados antes de «'+contenido+'».');
    actual={...nuevaActividadCartelera(),tipo,fecha,region,
     representacion:contenido.replace(/^Representaci[oó]n\s*:\s*/i,'').replace(/\s+$/,'')};
    registros.push(actual);grupoSede=[actual];gruposDeSede.push(grupoSede);ultimoCampo='';
    continue;
   }
   if(!actual)throw Error('Falta una representación consular antes de «'+contenido+'» (línea '+(numero+1)+').');
   const sinRotulo = /^(?:(?:lunes|martes|mi[eé]rcoles|jueves|viernes|s[aá]bado|domingo)\s+)?\d{1,2}\s+de\s+(?:enero|febrero|marzo|abril|mayo|junio|julio|agosto|septiembre|setiembre|octubre|noviembre|diciembre)(?:\s+del?\s+\d{4})?\.?$/i;
   const siguiente=lineas[numero+1]||'';
   const fechaSinRotulo=sinRotulo.test(contenido)&&(esHorario(siguiente)||/^Hora(?:rio(?: de atenci[oó]n)?)?\s*:/i.test(siguiente));
   const etiqueta=etiquetas.exec(contenido)||(fechaSinRotulo?['','Fecha',contenido]:null);
   if(etiqueta){
    const clave=etiqueta[1].normalize('NFD').replace(/\p{Diacritic}/gu,'').toLowerCase();
    const destino={lugar:'lugar',direccion:'lugar',hora:'horario',horario:'horario','horario de atencion':'horario',fecha:'fecha',ubicacion:'lugar',
     ciudad:'ciudad',servicio:'servicio',tramite:'servicio',
     'informacion adicional':'detalle',observacion:'detalle',observaciones:'detalle',nota:'detalle',requisito:'detalle',requisitos:'detalle'}[clave];
    if(destino==='fecha'){
     if(fechasExplicitas.has(actual)){
      if(!actual.horario)throw Error('Indique el horario de «'+(actual.fecha||actual.representacion)+'» antes de ingresar otra fecha.');
      // El mismo encabezado de oficina puede declarar dos fechas. Cada una conserva su horario.
      actual={...actual,fecha:'',horario:'',lugar:'',servicio:'',ciudad:'',detalle:''};
      registros.push(actual);grupoSede.push(actual);
     }
     fechasExplicitas.add(actual);
     actual.fecha=etiqueta[2].trim();ultimoCampo=actual.fecha?'':'fecha';continue;
    }
    aumentar(destino,etiqueta[2]);
    if(!etiqueta[2])ultimoCampo=destino;
   }else if(esHorario(contenido))aumentar('horario',contenido);
   else if(/^para\s+/i.test(contenido)){
    const destino=/^(Para\s+.+?)\s+en\s+(.+)$/i.exec(contenido);
    if(destino){
     aumentar('servicio',destino[1]);
     aumentar('ciudad',destino[2]);
    }else aumentar('servicio',contenido);
   }else if(tipo==='consulado'&&ultimoCampo==='horario'&&
      (/^(?:Plaza|Calle|Avenida|Bulevar|Boulevard|Carretera|Pasaje|Camino|Centro|Iglesia|Universidad)\s/i.test(contenido)||/^\d+\s+\S/.test(contenido))){
    aumentar('lugar',contenido);
   }else if(ultimoCampo==='lugar'||ultimoCampo==='detalle'||ultimoCampo==='servicio'){
    aumentar(ultimoCampo,contenido);
   }else aumentar('detalle',contenido);
  }
  if(!registros.length)throw Error('No se encontraron representaciones consulares en el texto.');
  for(const grupo of gruposDeSede.filter(g=>g.length>1)){
   // Un solo lugar o servicio se comparte entre fechas de la misma oficina. Si
   // se escribieron dos lugares diferentes, no se adivina cuál le falta a la otra fecha.
   for(const campo of ['lugar','servicio','ciudad']){
    const valores=[...new Set(grupo.map(r=>r[campo].trim()).filter(Boolean))];
    if(valores.length===1)for(const r of grupo)if(!r[campo])r[campo]=valores[0];
   }
  }
  for(const [i,r] of registros.entries()){
   if(!r.horario.trim())throw Error('Falta el horario de la actividad '+(i+1)+': '+r.representacion+'.');
  }
  return {registros,fechas,fechaPortada:fechaDePortadaCartelera(registros)};
}
function montarImportacionCartelera(panel,estado,version) {
  const modulo=document.createElement('details');
  modulo.className='sede-importar-cartelera';
  const resumen=document.createElement('summary');resumen.textContent='Pegar desde un documento';
  const ayuda=document.createElement('p');ayuda.className='field-help';
  ayuda.textContent='Pegar el listado completo y revisar los campos importados.';
  const area=document.createElement('textarea');area.rows=8;area.id='sedeTextoCartelera';
  area.setAttribute('aria-label','Texto base de jornadas y consulados móviles');
  area.placeholder='Jornadas extraordinarias del sábado 21 de noviembre\n\nEstados Unidos\n\nConsulado General de El Salvador en Nueva York, Nueva York\n9:00 a.m. a 1:00 p.m.';
  area.value=estado.listado||'';
  area.oninput=()=>{estado.listado=area.value;estado.avisoImportacion='';aviso.textContent='';};
  const aplicar=document.createElement('button');aplicar.type='button';aplicar.className='g';
  aplicar.textContent='Pasar al formulario';
  const aviso=document.createElement('p');aviso.setAttribute('role','status');
  aviso.className='field-help';aviso.textContent=estado.avisoImportacion||'';
  aplicar.onclick=()=>{
   try{
    const {registros,fechas,fechaPortada}=importarListadoCartelera(area.value,version);
    const anteriores=estado.registros.some(r=>actividadCarteleraConDatos(r,version==='mixta'?r.tipo:'consulado'));
    if(anteriores&&!confirm('¿Reemplazar las actividades actuales por las del texto pegado?'))return;
    estado.registros=registros;
    if(version==='mixta'){
     estado.fechas={...fechas};
     estado.fechaPortada=fechaPortada;
    }
    const jornadas=registros.filter(r=>r.tipo==='jornada').length;
    const moviles=registros.filter(r=>r.tipo==='consulado').length;
    estado.avisoImportacion=(jornadas?jornadas+' jornadas extraordinarias':'')+
     (jornadas&&moviles?' y ':'')+(moviles?moviles+' consulados móviles':'')+
     '. Revise los datos antes de descargar.'+
     (version==='mixta'&&!fechaPortada&&registros.some(r=>r.fecha)?' Revise también la fecha de la portada en Historia.':'');
    estado.listado=area.value;
    montarCartelera(version);
    go();
   }catch(error){aviso.textContent=error.message;}
  };
  modulo.open=!!estado.avisoImportacion;
  modulo.append(resumen,ayuda,area,aplicar,aviso);panel.append(modulo);
}

function planificarCartelera(g, version, historia = false, horizontal = false, omitidos = 0) {
 const ficha=cartelera[version], esMixta=version==='mixta';
 const registros=ficha.registros.slice(omitidos).filter(r=>actividadCarteleraConDatos(r,esMixta?r.tipo:'consulado'));
 const fichaConjunta=esMixta&&registros.length===1&&registros[0].tipo==='ambas';
 const paginas=[[]], limiteGeneral=horizontal?1191:historia?1830:esMixta?1310:1296;
 const limiteColumna=()=>horizontal&&paginas.at(-1)[0]?.clase==='titulo'&&paginas.at(-1)[0]?.contenido?.tipo==='consulado'&&paginas.length%2===0&&omitidos?924:limiteGeneral;
 const inicio=(i,op)=>{
  if(horizontal)return i%2?204:120;
  if(fichaConjunta&&op?.clase==='titulo')return historia?495:360;
  if(historia){
   if(op?.clase==='titulo')return 323;
   if(op?.clase==='actividad')return 344;
   return op?.contenido?.esJornada?350:286;
  }
  return esMixta?(i===0?104:135):142;
 };
 let y=inicio(0);
 function nuevaPagina(op){y=inicio(paginas.push([])-1,op);}
 function añadir(op){paginas.at(-1).push({...op,y});y+=op.alto;}
 const fechaEnArte=fecha=>fecha?fecha[0].toLocaleUpperCase('es')+fecha.slice(1):'';
 const previo=omitidos?ficha.registros[omitidos-1]:null;
 let anterior=previo?{tipo:previo.tipo,fecha:fechaEnArte(previo.fecha.trim()||ficha.fechas[previo.tipo].trim()),region:previo.region.trim()}:null;
 for(const registro of registros) {
  const tipo=esMixta?registro.tipo:'consulado', jornada=tipo==='jornada';
  const fechasCombinadas=tipo==='ambas'?[ficha.fechas.jornada.trim(),ficha.fechas.consulado.trim()]:[];
  const fechaBase=tipo==='ambas'?(fechasCombinadas[0]===fechasCombinadas[1]?fechasCombinadas[0]:''):ficha.fechas[tipo]||'';
  const fecha=fechaEnArte(registro.fecha.trim()||fechaBase.trim());
  const region=registro.region.trim();
  const cambioTipo=anterior?.tipo!==tipo, cambioFecha=anterior?.fecha!==fecha;
  const encabezados=[];
  if(horizontal&&omitidos&&cambioTipo&&tipo==='consulado'&&paginas.length%2===1&&paginas.at(-1).length)
   nuevaPagina();
  // En X, un nuevo tramo de fechas del mismo tipo arranca en una lámina nueva.
  if(horizontal&&!cambioTipo&&cambioFecha&&fecha&&anterior&&paginas.at(-1).length){
   if(paginas.length%2===1)paginas.push([]);
   nuevaPagina();
  }
  if(cambioTipo&&esMixta){
   const alto=horizontal&&!jornada?224:historia?(jornada?273:242):183;
   encabezados.push({clase:'titulo',alto:alto-(fecha||fechasCombinadas.some(Boolean)?0:40),
    contenido:{tipo,fecha,fechasCombinadas}});
  }else if(cambioFecha&&fecha&&(anterior||registro.fecha.trim())){
   encabezados.push({clase:'fecha',alto:historia?70:65,contenido:fecha});
  }
  const encabezadoRegional=region?{
   clase:'region',alto:historia?(jornada?92:70):(jornada?71:80),contenido:{region,esJornada:jornada}
  }:null;
  if(encabezadoRegional&&(cambioTipo||cambioFecha||region!==anterior?.region))
   encabezados.push(encabezadoRegional);
  anterior={tipo,fecha,region};
  const paso=jornada?(historia?30:horizontal?30:27.5):(historia?23.5:horizontal?23:22);
  const tamano=jornada?(historia?25:horizontal?27:23):(historia?22:horizontal?23:20);
  const fuente='300 '+tamano+'px '+L;
  const azul=tonosCartelera.azul, ancho=historia?803:815;
  const partesServicio=[registro.servicio.trim(),registro.ciudad.trim()].filter(Boolean);
  const servicio=partesServicio.join(' en ');
  const lugar=registro.lugar.trim();
  const datos=[
   [registro.representacion,azul],
   ...(!jornada&&servicio?[[servicio,'#168bd0','500 '+tamano+'px "Museo Sans oficial"']]:[]),
   [registro.horario,azul],
   ...(!jornada&&lugar?[['Lugar: '+lugar,azul]]:[]),
   ...(registro.detalle.trim()?[[registro.detalle.trim(),azul]]:[])
  ];
  const separar=(datos,top)=>{
   const lineas=[];
   g.font=fuente;
   for(const [dato,color,fuenteLinea=fuente] of datos){
    g.font=fuenteLinea;
    for(const parrafo of (dato||'').split('\n').map(t=>t.trim()).filter(Boolean)){
     let restante=protegerToponimos(parrafo);
     while(restante){
      const estrecho=esMixta&&!historia&&!horizontal;
      const esDireccion=dato.startsWith('Lugar:');
      const cierreHorizontal=horizontal&&cambioFecha&&!cambioTipo;
      const juntoAFirma=estrecho&&top+lineas.length*paso<280;
      const disponible=juntoAFirma?(top+lineas.length*paso<200?440:585):
       cierreHorizontal?1200:horizontal?(jornada?656:esDireccion?724:ancho):
       historia&&esDireccion?750:estrecho&&esDireccion?752:ancho;
      const partes=lineasEditorial(g,restante,disponible);
      if(!partes.length)break;
      // Con ancho variable solo la primera línea se mide junto a la firma.
      const [primera,...resto]=partes;
      lineas.push([primera,fuenteLinea,color]);
      restante=resto.join(' ');
     }
    }
   }
   return lineas;
  };
  const hueco=jornada?(historia?30:horizontal?34:28):(historia?21:horizontal?24:23);
  const estimado=encabezados.reduce((s,o)=>s+o.alto,0);
  const referencia=encabezados[0]||{clase:'actividad',contenido:{esJornada:jornada}};
  // Zona libre frente a la firma (724–968 px; su base está a 206 px).
  // Si una línea extensa se aproxima al logotipo, se baja el bloque completo.
  const margenLogo=280, anchoLibreLogo=724-207-20;
  const seAcercaAlLogo=(lineas, inicioTexto)=>{
   if(historia||horizontal||esMixta||inicioTexto>=margenLogo)return false;
   g.font=fuente;
   return lineas.some(([texto],i)=>inicioTexto+i*paso<margenLogo &&
    g.measureText(texto).width>anchoLibreLogo);
  };
  const ajustarInicioPorLogo=(lineasRegistro,altoEncabezados=estimado)=>{
   const inicioTexto=y+altoEncabezados;
   if(!seAcercaAlLogo(lineasRegistro,inicioTexto))return lineasRegistro;
   y+=margenLogo-inicioTexto;
   return separar(datos,y+altoEncabezados);
  };
  if(!paginas.at(-1).length)y=inicio(paginas.length-1,referencia);
  let lineasRegistro=ajustarInicioPorLogo(separar(datos,y+estimado),estimado);
  if(y+estimado+lineasRegistro.length*paso+hueco>limiteColumna()&&paginas.at(-1).length){
   if(!esMixta&&encabezadoRegional&&!encabezados.includes(encabezadoRegional))encabezados.push(encabezadoRegional);
   nuevaPagina(encabezados[0]||referencia);
   const altoNuevaPagina=encabezados.reduce((total,op)=>total+op.alto,0);
   lineasRegistro=ajustarInicioPorLogo(separar(datos,y+altoNuevaPagina),altoNuevaPagina);
  }
  for(const op of encabezados)añadir(op);
  while(lineasRegistro.length){
   // También proteger los fragmentos que continúan en una página nueva.
   if(seAcercaAlLogo(lineasRegistro,y))y=Math.max(y,margenLogo);
   const capacidad=Math.max(1,Math.floor((limiteColumna()-y)/paso));
   const parte=lineasRegistro.splice(0,capacidad);
   añadir({clase:'actividad',alto:parte.length*paso+hueco,
    contenido:{paso,lineasRegistro:parte,esJornada:jornada,hueco}});
   if(lineasRegistro.length){
    nuevaPagina(encabezadoRegional||{clase:'actividad',contenido:{esJornada:jornada}});
    if(encabezadoRegional)añadir(encabezadoRegional);
   }
  }
 }
 if(!paginas[0].length&&esMixta&&!omitidos)añadir({clase:'titulo',alto:148,contenido:{tipo:'jornada',fecha:''}});
 return paginas;
}

const cabecerasCarteleraHumanas = new Map();
async function precargarCabeceraCartelera(formato) {
 const claves=['jornadas','consulados'].map(tipo=>formato+'-'+tipo);
 await Promise.all(claves.map(async clave=>{
  if(!cabecerasCarteleraHumanas.has(clave)){
   const pendiente=img('assets/cartelera-'+clave+'.png').catch(error=>{
    cabecerasCarteleraHumanas.delete(clave);throw error;
   });
   cabecerasCarteleraHumanas.set(clave,pendiente);
  }
  const recurso=await cabecerasCarteleraHumanas.get(clave);
  cabecerasCarteleraHumanas.set(clave,recurso);
 }));
}
function pintarTituloHumanoCartelera(g,tipo,formato,x,y,ancho) {
 const recurso=cabecerasCarteleraHumanas.get(formato+'-'+tipo);
 if(!recurso?.naturalWidth)throw Error('No se pudo abrir el título original de la cartelera.');
 const alto=ancho*recurso.naturalHeight/recurso.naturalWidth;
 g.drawImage(recurso,x,y,ancho,alto);
 return y+alto;
}

function dibujarTituloCartelera(g, y, {tipo, fecha, fechasCombinadas}, historia = false, horizontal = false) {
 const {azul, claro, blanco} = tonosCartelera;
 const consulado = tipo === 'consulado';
 const banda = (texto, x, alto, ancho, angulo, fondo, font, top) => {
  g.save();
  g.translate(x, y + top);
  g.rotate(angulo);
  g.fillStyle = fondo;
  g.fillRect(0, 0, ancho, alto);
  g.fillStyle = blanco;
  g.font = font;
  g.textBaseline = 'middle';
  g.fillText(texto, 10, alto / 2 + 1, ancho - 20);
  g.restore();
 };
 if (tipo === 'ambas') {
  banda('Jornadas extraordinarias',120,52,542,-.025,azul,'700 37px ' + F,9);
  banda('y consulados móviles',170,51,480,.012,claro,'700 37px ' + F,56);
  const [jornada, consulado] = fechasCombinadas;
  const fechas = fecha ? [fecha] : [jornada && 'Jornadas: ' + jornada, consulado && 'Consulados: ' + consulado].filter(Boolean);
  for (const [i, texto] of fechas.entries()) {
   g.font = '700 18px ' + F;
   g.textBaseline = 'middle';
   const top = y + 116 + i * 25;
   const ancho = Math.min(520,g.measureText(texto).width + 28);
   g.fillStyle = blanco;g.fillRect(120,top,ancho,24);
   g.fillStyle = azul;g.fillText(texto,132,top+12,ancho-24);
  }
  return;
 }
 const formato=historia?'historia':horizontal?'x':'post';
 const dimension=historia?(consulado?[122,550/1.35]:[119,675/1.35]):
  horizontal?(consulado?[126,550]:[102,587/1.2]):
  consulado?[146.75,422]:[119.5,489];
 const borde=pintarTituloHumanoCartelera(g,consulado?'consulados':'jornadas',formato,dimension[0],y+(consulado?2:-3),dimension[1]);
 if (fecha) {
  g.font = '500 22px "Cartelera Poppins"';
  const ancho = Math.min(515,Math.max(150,g.measureText(fecha).width+(historia?55:35)));
  const izquierda=consulado?(historia?175:horizontal?167:193):(historia?190:horizontal?198:196);
  const alto=historia?34:horizontal?34:39;
  const base=borde+1;
  g.fillStyle = blanco;
  g.fillRect(izquierda,base,ancho,alto);
  g.strokeStyle = claro;
  g.strokeRect(izquierda,base,ancho,alto);
  g.fillStyle = azul;
  g.textAlign='left';g.textBaseline = 'middle';
  g.fillText(fecha,izquierda+14,base+alto/2+1,ancho-27);
 }
}

function dibujarCarteleraSede(g, operaciones, historia = false, columna = false) {
 const {fondo, azul, blanco, logo} = tonosCartelera;
 if(!columna){
  g.fillStyle = fondo;
  g.fillRect(0, 0, 1080, historia ? 1920 : 1350);
 }
 if (columna) {
  // La firma se dibuja una sola vez para las dos columnas.
 } else if (historia) {
  const ancha = operaciones.some(op => op.contenido?.esJornada || op.contenido?.tipo === 'jornada');
  const tituloMovil = operaciones.some(op => op.clase === 'titulo' && op.contenido?.tipo === 'consulado');
  // La firma vectorial del HTML conserva el tamaño y el anclaje de la historia aprobada.
  if(tituloMovil) sedeFirma(g,398.5,138,312,logo,false);
  else sedeFirma(g, ancha ? 388 : 418, 141, ancha ? 304 : 244, logo, false);
 } else if (operaciones.some(op=>op.clase==='titulo' && op.contenido.tipo==='ambas' && op.y===360)) {
  sedeFirma(g,388,127,304,logo,false);
 } else sedeFirma(g,724,101,244,logo,false);
 const circulo = (x, y, radio, relleno, contorno) => {
  g.beginPath();
  g.arc(x, y, radio, 0, 2 * Math.PI);
  g.fillStyle = relleno;
  g.fill();
  if (contorno) { g.strokeStyle = contorno; g.stroke(); }
 };
 let anterior;
 for (const {clase, y, contenido} of operaciones) {
  if (clase === 'titulo') {
   if (historia) {
    g.save();
    g.translate(contenido.tipo === 'consulado' ? 87 : 24, y);
    g.scale(1.35, 1.35);
    dibujarTituloCartelera(g, 0, contenido, true);
    g.restore();
   } else dibujarTituloCartelera(g,y,contenido,false,columna);
   anterior = undefined;
   continue;
  }
  const grande = historia && contenido?.esJornada;
  const centro = y + (clase === 'region' ? (grande ? 23 : 19) : 15);
  if (anterior !== undefined) {
   g.strokeStyle = azul;
   g.lineWidth = 0.7;
   g.beginPath();
   g.moveTo(151, anterior);
   g.lineTo(151, centro);
   g.stroke();
  }
  anterior = centro;
  if (clase === 'fecha') {
   const x = columna ? 126 : 151;
   g.font = '500 22px "Cartelera Poppins"';
   const ancho = Math.min(774, Math.max(150, g.measureText(contenido).width + (historia ? 110 : columna ? 85 : 44)));
   g.fillStyle = blanco;
   const alto = historia ? 46 : 40;
   g.fillRect(x, y, ancho, alto);
   g.strokeStyle = tonosCartelera.claro;
   g.strokeRect(x, y, ancho, alto);
   g.fillStyle = azul;
   g.textBaseline = 'middle';
   g.fillText(contenido, x + 15, y + alto / 2 + 1, ancho - 30);
   anterior = y + alto;
  } else if (clase === 'region') {
   const {region} = contenido;
   const alto = grande ? 46 : 39;
   g.font = '600 ' + (grande ? 39 : 32) + 'px "Cartelera Poppins"';
   sedeCaja(g, 126, y, Math.min(555, Math.max(161, g.measureText(region).width + (grande ? 99 : 91))), alto, alto / 2, azul);
   circulo(151, centro, grande ? 18 : 15, blanco);
   circulo(151, centro, grande ? 9 : 7.5, azul);
   g.fillStyle = blanco;
   g.textBaseline = 'middle';
   g.fillText(region, 185, centro + 1, 475);
  } else {
   circulo(151, centro, 14.5, blanco, azul);
   circulo(151, centro, 7, azul);
   const {paso, lineasRegistro} = contenido;
   g.textBaseline = 'top';
   for (const [i, [texto, fuente, color]] of lineasRegistro.entries()) {
    g.fillStyle = color;
    g.font = fuente;
    g.fillText(texto, 207, y + i * paso);
   }
  }
 }
}


function dibujarPortadaCartelera(g, fecha) {
 const {fondo, azul, claro, blanco} = tonosCartelera;
 g.fillStyle = fondo;
 g.fillRect(0, 0, 1080, 1920);
 g.textAlign = 'center';
 g.textBaseline = 'middle';
 const centrado = (texto, y, tamaño, peso, color, ancho = 840, familia = '"Cartelera Poppins"') => {
  g.fillStyle = color;
  g.font = peso + ' ' + tamaño + 'px ' + familia;
  g.fillText(texto, 540, y, ancho);
 };
 const bloque = (y, ancho, angulo, color, primera, segunda) => {
  g.save();
  g.translate(540, y);
  g.rotate(angulo);
  g.translate(-540, -y);
  g.fillStyle = color;
  g.fillRect((1080 - ancho) / 2, y, ancho, 242);
  centrado(primera, y + 74, 84.6, 400, blanco, ancho - 45);
  centrado(segunda, y + 176, 84.6, 600, blanco, ancho - 45);
  g.restore();
 };
 centrado('Te presentamos las próximas', 514, 48, 500, azul);
 bloque(580, 744, 0.021, claro, 'Jornadas', 'extraordinarias');
 bloque(859, 627, -0.035, azul, 'Consulados', 'móviles');
 g.fillStyle = blanco;
 g.beginPath();
 g.arc(540, 846, 46, 0, 2 * Math.PI);
 g.fill();
 centrado('y', 846, 67.7, 500, azul, 840, '"Museo Sans oficial"');
 centrado('en el exterior.', 1190, 48, 500, azul);
 if (fecha) {
  g.font='500 44.1px "Cartelera Poppins"';
  const ancho=Math.max(730,Math.min(897,g.measureText(fecha).width+36));
  const x=ancho===730?174:(1080-ancho)/2;
  const filas=lineasEditorial(g,fecha,ancho-36);
  const alto=filas.length<2?78:52*filas.length+27;
  g.fillStyle=blanco;g.fillRect(x,1295,ancho,alto);
  g.strokeStyle=claro;g.strokeRect(x,1295,ancho,alto);
  filas.forEach((fila,i)=>centrado(fila,1334+i*52,44.1,500,azul,ancho-36));
 }
}

// Una apertura horizontal reparte las fichas por región, no por columnas estancas.
function planAperturaRegionalX(g) {
 const ficha=cartelera.mixta;
 const grupos=[];
 for(const r of ficha.registros){
  if(r.tipo!=='jornada'||!r.region.trim()||!actividadCarteleraConDatos(r,r.tipo))break;
  const region=r.region.trim(),fecha=r.fecha.trim()||ficha.fechas.jornada.trim();
  const k=grupos.at(-1);
  if(k&&fecha!==k.fecha)break;
  if(k?.region===region)k.registros.push(r);
  else grupos.push({region,fecha,registros:[r]});
 }
 // La retícula ancha aparece cuando hay un bloque principal y otro breve.
 // Listados pequeños o regiones con poco espacio siguen usando la paginación común.
 if(grupos.length<2||grupos[0].registros.length<5||grupos[1].registros.length>3)return null;
 const columnasGrupo=g=>g.registros.length<=3?Math.max(1,g.registros.length):2;
 const ajustes=[];
 let y=318, cantidad=0;
 for(const [i,grupo] of grupos.slice(0,2).entries()){
  const n=columnasGrupo(grupo), ancho=(1638-(n-1)*38)/n;
  const q=Math.ceil(grupo.registros.length/n), inicio=y, paso=27.5;
  const fuente='300 26px "Museo Sans oficial"';
  g.font=fuente;
  const columnas=Array.from({length:n},(_,col)=>grupo.registros.slice(col*q,(col+1)*q).map(r=>{
   const lineas=[r.representacion,r.horario,r.detalle].flatMap(t=>lineasEditorial(g,t||'',ancho-49));
   return {lineas,alto:lineas.length*paso+31};
  }));
  const altos=Array.from({length:q},(_,fila)=>Math.max(0,...columnas.map(c=>c[fila]?.alto||0)));
  const fin=y+77+altos.reduce((s,a)=>s+a,0);
  if(fin>991||!altos.length)return null;
  ajustes.push({region:grupo.region,y:inicio,ancho,columnas,altos,fuente,paso});
  y=fin+15;cantidad+=grupo.registros.length;
 }
 const primero=grupos[0].fecha;
 return {ajustes,cantidad,fecha:primero?primero[0].toLocaleUpperCase('es')+primero.slice(1):''};
}

function dibujarAperturaRegionalX(g,plan) {
 const {fondo,azul,blanco,logo}=tonosCartelera;
 g.fillStyle=fondo;g.fillRect(0,0,1920,1080);
 sedeFirma(g,1504,118,228,logo,false);
 g.save();g.translate(20,70);g.scale(1.20,1.20);
 dibujarTituloCartelera(g,0,{tipo:'jornada',fecha:plan.fecha},false,true);
 g.restore();
 const circulo=(x,y,r,fill,stroke)=>{
  g.beginPath();g.arc(x,y,r,0,Math.PI*2);g.fillStyle=fill;g.fill();
  if(stroke){g.strokeStyle=stroke;g.stroke();}
 };
 for(const grupo of plan.ajustes){
  const {region,y,ancho,columnas,altos,fuente,paso}=grupo;
  g.font='600 42px "Cartelera Poppins"';
  const w=Math.min(610,Math.max(151,g.measureText(region).width+79));
  sedeCaja(g,129,y,w,44,22,azul);
  circulo(153,y+22,16,blanco);circulo(153,y+22,7.5,azul);
  g.textAlign='left';g.textBaseline='middle';g.fillStyle=blanco;g.fillText(region,186,y+23,w-63);
  for(const [j,col] of columnas.entries()){
   const x=153+j*(ancho+38);
   let top=y+77,ultimo=null;
   for(const [i,item] of col.entries()){
    if(ultimo!==null){
     g.strokeStyle=azul;g.lineWidth=.8;g.beginPath();g.moveTo(x,ultimo);g.lineTo(x,top+12);g.stroke();
    }
    ultimo=top+12;circulo(x,ultimo,14,fondo,azul);circulo(x,ultimo,7,azul);
    g.font=fuente;g.fillStyle=azul;g.textBaseline='top';
    item.lineas.forEach((t,l)=>g.fillText(t,x+44,top+l*paso,ancho-49));
    top+=altos[i];
   }
  }
 }
}

function dibujarCarteleraX(g,columnas){
 const {fondo,logo}=tonosCartelera;
 g.fillStyle=fondo;g.fillRect(0,0,1920,1080);
 sedeFirma(g,1504,118,244,logo,false);
 columnas.forEach((ops,i)=>{
  const cierreBreve=columnas.length===1&&ops[0]?.clase==='fecha'&&ops.filter(o=>o.clase==='actividad').length<=2;
  const cambioSeccion=columnas[1]?.[0]?.clase==='titulo'&&columnas[1][0].contenido.tipo==='consulado';
  const inicial=cierreBreve?254:cambioSeccion?78:
   i===1&&!ops.some(o=>o.clase==='titulo')?78:0;
  const fin=Math.max(1,...ops.map(o=>o.y+o.alto));
  const escala=Math.min(1,(1040-inicial)/fin);
  g.save();g.translate(cierreBreve?80:i?860:6,inicial);g.scale(escala,escala);
  dibujarCarteleraSede(g,ops,false,true);
  g.restore();
 });
}
async function prepararCarteleraSede(version, formato) {
 await Promise.all([
  document.fonts.load('300 23px MuseoL'),document.fonts.load('500 22px "Museo Sans oficial"'),document.fonts.load('300 26px "Museo Sans oficial"'),
  document.fonts.load('700 32px "Museo Sans"'),document.fonts.load('700 32px "AD Poppins"','ÁÉÍÓÚ ñ Panamá México')
 ]);
 const historia = version === 'mixta' && formato === 'historia';
 const horizontal = version === 'mixta' && formato === 'x';
 await Promise.all([
  precargarCabeceraCartelera(historia?'historia':horizontal?'x':'post'),
  ...(historia?[400,500,600]:[500,600]).map(async peso=>{
   const fuentes=await document.fonts.load(peso+' 28px "Cartelera Poppins"','Sábado México Estados Unidos');
   if(!fuentes.some(c=>c.status==='loaded'))throw Error('No se pudo cargar la tipografía de la cartelera.');
  })
 ]);
 const ancho=horizontal?1920:1080, alto=horizontal?1080:historia?1920:1350;
 const g = document.createElement('canvas').getContext('2d');
 const crearArte = (sufijo, dibujar) => ({
  nombre: 'cartelera-colectiva-' + version + (historia ? '-historia-' : horizontal ? '-x-' : '-') + sufijo + '.png',
  ancho, alto,
  dibujar(escala, banda) {
   const lienzo = lienzoArte(ancho, alto, escala, banda);
   dibujar(lienzo.g);
   return lienzo.c;
  }
 });
 const apertura=horizontal?planAperturaRegionalX(g):null;
 const plan=planificarCartelera(g,version,historia,horizontal,apertura?.cantidad||0);
 const numerar=n=>String(n).padStart(2,'0');
 const artes=horizontal ? [
  ...(apertura?[crearArte('01',g=>dibujarAperturaRegionalX(g,apertura))]:[]),
  ...plan.filter((ops,i)=>i%2===0&&(ops.length||plan[i+1]?.length)).map((_,i)=>
   crearArte(numerar(i+(apertura?2:1)),g=>dibujarCarteleraX(g,plan.slice(i*2,i*2+2))))
 ] :
  plan.map((operaciones,i)=>crearArte(numerar(i+(historia?2:1)),g=>dibujarCarteleraSede(g,operaciones,historia)));
 if (historia) {
  const fecha = cartelera.mixta.fechaPortada.trim();
  artes.unshift(crearArte('01-portada', g => dibujarPortadaCartelera(g, fecha)));
  imagenContraportada ||= img('assets/contraportada-consulado-virtual.png').catch(error=>{imagenContraportada=null;throw error;});
  const imagen = await imagenContraportada;
  artes.push(crearArte(numerar(artes.length+1)+'-contraportada', g => g.drawImage(imagen,0,0,1080,1920)));
 }
 return artes;
}

async function prepararArteSede(seleccion=seleccionSede(),parte) {
 const {diseno,version,plantilla,estado,formato,alto} = seleccion;
 const {texto,color,foto,encuadre} = estado;
 if (!fuentesSede) {
  const muestra = 'ÁÉÍÓÚ áéíóú Ññ';
  fuentesSede = Promise.all([sedeFuente(40,900),sedeFuente(40,700),sedeFuente(40,300),
   sedeFuente(40,400,'montserrat'),sedeFuente(40,700,'montserrat'),sedeFuente(40,700,'poppins'), '400 40px "AD Raleway"']
   .map(fuente => document.fonts.load(fuente,muestra))).catch(() => {});
 }
 const {foto: ejemplo} = plantilla;
 const referencia=!foto&&diseno==='oficinas'&&(estado.paleta===undefined||estado.paleta==='original')&&(
  version==='v5'?(alto===1920?'curvaHistoria':'curvaPost'):version==='v4'&&alto===1350&&'serviciosPost'
 );
 const recurso=foto||(ejemplo&&(
  referencia?(fotosSede[referencia]||=img(fotosReferenciaSede[referencia])):
   (fotosSede[ejemplo]||=img(fotosEjemploSede[ejemplo]))
 ));
 const [imagen] = await Promise.all([recurso,fuentesSede, ...((version === 'v8' || version === 'v9') ? [sedeElementosListos] : [])]);
 const copiaTexto = {...texto}, copiaColor = {...color}, copiaEncuadre = {...encuadre};
 return {
  nombre: (version === 'v8' ? 'oficinas-parte-1-mapa' : version === 'v9' ? 'oficinas-parte-2-directorio' : diseno + '-regionales-' + version) + '-' + formato + '.png',
  ancho: anchoSede, alto, parteSede:parte?.id,tituloPagina:parte?.titulo,
  dibujar(K,banda) {
   const {c,g} = lienzoArte(anchoSede,alto,K,banda);
   g.fillStyle = copiaColor.fondo;
   g.fillRect(0,0,anchoSede,alto);
   plantilla.dibujar(g,alto,copiaTexto,copiaColor,imagen,copiaEncuadre,!!referencia);
   if(g.desbordeEditorial)this.desborde=true;
   return c;
  }
 };
}

