// Controles de seguridad del sitio estático. No interpretar texto como código.
(function(){
 const reemitidos=new WeakSet();
 const validacionesArchivo=new WeakMap();
 const maxImagen=20*1024*1024,maxJson=2*1024*1024;
 async function comprobar(f,json){
  if(f.size===0||f.size>(json?maxJson:maxImagen))throw Error(json?'Cargar un JSON de hasta 2 MB.':'Cargar imágenes de hasta 20 MB por archivo.');
  if(json){if(!/\.json$/i.test(f.name))throw Error('Seleccionar un archivo JSON.');return;}
  const b=new Uint8Array(await f.slice(0,16).arrayBuffer());
  const png=b.length>=8&&[137,80,78,71,13,10,26,10].every((v,i)=>b[i]===v);
  const jpg=b[0]===255&&b[1]===216&&b[2]===255;
  const webp=b.length>=12&&String.fromCharCode(...b.slice(0,4))==='RIFF'&&String.fromCharCode(...b.slice(8,12))==='WEBP';
  if(!png&&!jpg&&!webp)throw Error('Cargar una imagen válida en PNG, JPG o WebP.');
  const u=URL.createObjectURL(f);
  try{const im=new Image();im.src=u;await im.decode();if(im.naturalWidth>12000||im.naturalHeight>12000||im.naturalWidth*im.naturalHeight>40000000)throw Error('Reducir las dimensiones de la imagen antes de cargarla.');}finally{URL.revokeObjectURL(u);}
 }
 document.addEventListener('change',async ev=>{
  const el=ev.target;if(!el.matches?.('input[type=file]')||reemitidos.has(el)||!el.files.length)return;
  ev.stopImmediatePropagation();const files=Array.from(el.files),json=el.id==='proyFile';
  const token={};validacionesArchivo.set(el,token);
  const actual=()=>el.isConnected&&validacionesArchivo.get(el)===token&&files.length===el.files.length&&files.every((f,i)=>f===el.files[i]);
  // Invalidar una selección anterior mientras se valida la nueva.
  if(json){const boton=document.getElementById('proyFileBtn');if(boton)boton.disabled=true;}

  try{if(files.length>4)throw Error('Cargar hasta cuatro archivos a la vez.');if(!json&&files.reduce((n,f)=>n+f.size,0)>40*1024*1024)throw Error('Cargar hasta 40 MB de imágenes por selección.');for(const f of files){if(!actual())return;await comprobar(f,json);}if(!actual())return;reemitidos.add(el);try{el.dispatchEvent(new Event('change',{bubbles:true}));}finally{reemitidos.delete(el);}}
  catch(error){if(!actual())return;el.value='';
   if(json){reemitidos.add(el);try{el.dispatchEvent(new Event('change',{bubbles:true}));}finally{reemitidos.delete(el);}}
   alert(error.message||'No se pudo abrir el archivo.');}
 },true);
 // Evitar que un pegado masivo bloquee el editor. No recortar información sin aviso.
 document.addEventListener('paste',ev=>{
  const el=ev.target;if(!el.matches?.('textarea,input:not([type]),input[type=text],input[type=search],input[type=email],input[type=url]'))return;
  const texto=ev.clipboardData?.getData('text/plain');if(typeof texto!=='string')return;
  const limite=el.id==='proyRaw'?2*1024*1024:el.tagName==='TEXTAREA'?250000:30000;
  const ocupados=el.value.length-Math.max(0,(el.selectionEnd??0)-(el.selectionStart??0));
  if(ocupados+texto.length>limite){ev.preventDefault();alert('El texto supera el tamaño permitido. Dividirlo antes de pegarlo.');}
 },true);
 const acciones={
 'add()':()=>add(), 'MVAplicarPegado()':()=>MVAplicarPegado(),
 'MVRemovePhoto()':()=>MVRemovePhoto(), "MVAdd($('mvNewType').value)":()=>MVAdd($('mvNewType').value),
 'MVActualizarPegado(this.value)':e=>MVActualizarPegado(e.value),
 'mvEditor.seleccion=Number(this.value)':e=>{mvEditor.seleccion=Number(e.value)},
 'MVDesign(this.value)':e=>MVDesign(e.value), 'registrarCarga(MVPhoto(this),this)':e=>registrarCarga(MVPhoto(e),e),
 "MVS('photoY',+this.value)":e=>MVS('photoY',+e.value),
 'mvEditor.importarAbierto=this.open':e=>{mvEditor.importarAbierto=e.open},
 'mvEditor.disenoAbierto=this.open':e=>{mvEditor.disenoAbierto=e.open}
 };
 for(const tipo of ['click','input','change','toggle'])document.addEventListener(tipo,ev=>{
  const el=ev.target.closest?.('[data-sec-'+tipo+']');if(!el||el.disabled)return;
  const a=el.getAttribute('data-sec-'+tipo);let m,i;
  if(Object.hasOwn(acciones,a)){acciones[a](el);return;}
  if((m=/^S\[(\d+)\]\.([cfhd])=this\.value;go\(\)$/.exec(a))&&(i=Number(m[1]))<S.length){S[i][m[2]]=el.value;go();return;}
  if((m=/^S\.splice\((\d+),1\);form\(\);go\(\)$/.exec(a))&&(i=Number(m[1]))<S.length&&S.length>1){S.splice(i,1);form();go();return;}
  if((m=/^MVS\('(heroTitle|heroText|programTitle)',this\.value\)$/.exec(a))){MVS(m[1],el.value);return;}
  if((m=/^MVB\((\d+),'(t|x|width|icon)',this\.value\)$/.exec(a))&&(i=Number(m[1]))<MP().blocks.length){MVB(i,m[2],el.value);return;}
  if((m=/^MVCambiarTipo\((\d+),this\.value\)$/.exec(a))&&(i=Number(m[1]))<MP().blocks.length){MVCambiarTipo(i,el.value);return;}
  if((m=/^MVMove\((\d+),(-1|1)\)$/.exec(a))&&(i=Number(m[1]))<MP().blocks.length){MVMove(i,Number(m[2]));return;}
  if((m=/^MV(Dup|Delete)\((\d+)\)$/.exec(a))&&(i=Number(m[2]))<MP().blocks.length){(m[1]==='Dup'?MVDup:MVDelete)(i);return;}
  if((m=/^dl\((\d+)\)$/.exec(a))&&(i=Number(m[1]))<pageSpecs.length){dl(i);return;}
 },true);

})();
